CREATE FUNCTION academy._agg_assert_tenant(_tenant_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
BEGIN
  IF _tenant_id IS NULL THEN RAISE EXCEPTION 'tenant_id required'; END IF;
  IF NOT (academy.is_tenant_member(auth.uid(), _tenant_id) OR academy.is_platform_admin(auth.uid())) THEN
    RAISE EXCEPTION 'Not authorized for tenant';
  END IF;
END;
$$;


