--
-- Name: _sync_user_role_from_profile(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy._sync_user_role_from_profile() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
  mapped academy.app_role;
BEGIN
  mapped := CASE NEW.role
    WHEN 'owner' THEN 'owner'::academy.app_role
    WHEN 'coach' THEN 'admin'::academy.app_role
    ELSE 'admin'::academy.app_role
  END;
  IF TG_OP = 'UPDATE' AND OLD.role IS DISTINCT FROM NEW.role THEN
    DELETE FROM academy.user_roles
      WHERE user_id = NEW.user_id AND tenant_id = NEW.tenant_id;
  END IF;
  INSERT INTO academy.user_roles(user_id, tenant_id, role)
  VALUES (NEW.user_id, NEW.tenant_id, mapped)
  ON CONFLICT (user_id, tenant_id, role) DO NOTHING;
  RETURN NEW;
END; $$;


--
-- Name: acquire_match_scoring_lock(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.acquire_match_scoring_lock(_match_id uuid, _session_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
  m record;
  lock_row record;
  stale_after interval := interval '90 seconds';
BEGIN
  SELECT id, tenant_id INTO m FROM academy.mc_matches WHERE id = _match_id;
  IF m.id IS NULL THEN RAISE EXCEPTION 'match not found'; END IF;
  IF NOT academy.is_tenant_member(auth.uid(), m.tenant_id) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  SELECT * INTO lock_row FROM academy.mc_scoring_locks WHERE match_id = _match_id FOR UPDATE;

  IF lock_row.match_id IS NULL THEN
    INSERT INTO academy.mc_scoring_locks (match_id, tenant_id, owner_user_id, session_id)
    VALUES (_match_id, m.tenant_id, auth.uid(), _session_id);
    RETURN TRUE;
  END IF;

  IF lock_row.owner_user_id = auth.uid() THEN
    UPDATE academy.mc_scoring_locks
      SET session_id = _session_id, last_heartbeat_at = now()
      WHERE match_id = _match_id;
    RETURN TRUE;
  END IF;

  IF lock_row.last_heartbeat_at < now() - stale_after THEN
    UPDATE academy.mc_scoring_locks
      SET owner_user_id = auth.uid(),
          session_id = _session_id,
          acquired_at = now(),
          last_heartbeat_at = now()
      WHERE match_id = _match_id;
    RETURN TRUE;
  END IF;

  RETURN FALSE;
END; $$;


--
-- Name: admin_set_student_password(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.admin_set_student_password(_tenant_id uuid, _student_id uuid, _new_password text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy', 'extensions'
    AS $$
DECLARE
  _user_id UUID;
BEGIN
  -- Verify caller is owner or admin of this tenant
  IF NOT (academy.has_role(auth.uid(), 'owner', _tenant_id) OR academy.has_role(auth.uid(), 'admin', _tenant_id)) THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  -- Get user_id from student
  SELECT user_id INTO _user_id FROM academy.students WHERE id = _student_id AND tenant_id = _tenant_id;
  
  IF _user_id IS NULL THEN
    RAISE EXCEPTION 'Student user not found';
  END IF;

  -- Update auth.users directly. 
  -- Note: This requires the function owner (usually postgres) to have permission to write to auth.users.
  UPDATE auth.users 
  SET encrypted_password = extensions.crypt(_new_password, extensions.gen_salt('bf')) 
  WHERE id = _user_id;
END;
$$;


--
-- Name: advance_lead_stage(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.advance_lead_stage(_lead_id uuid, _new_stage text, _remark text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
  l academy.leads%ROWTYPE;
  tl_id uuid;
BEGIN
  SELECT * INTO l FROM academy.leads WHERE id = _lead_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Lead not found'; END IF;
  IF NOT (academy.is_tenant_member(auth.uid(), l.tenant_id) OR academy.is_platform_admin(auth.uid())) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  IF _new_stage NOT IN ('new','contacted','counselling','trial','decision','approved','rejected','converted') THEN
    RAISE EXCEPTION 'Invalid stage %', _new_stage;
  END IF;

  UPDATE academy.leads
     SET pipeline_stage = _new_stage,
         status = CASE _new_stage
           WHEN 'converted' THEN 'won'
           WHEN 'rejected' THEN 'lost'
           WHEN 'contacted' THEN 'contacted'
           ELSE status END
   WHERE id = _lead_id;

  INSERT INTO academy.admission_timeline
    (tenant_id, lead_id, event_type, from_stage, to_stage, remark, actor_id)
  VALUES
    (l.tenant_id, l.id, 'stage_changed', l.pipeline_stage, _new_stage, _remark, auth.uid())
  RETURNING id INTO tl_id;

  RETURN tl_id;
END; $$;


