--
-- Name: assign_billing_invoice_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.assign_billing_invoice_number() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $_$
DECLARE
  year_part text;
  next_num int;
  candidate text;
BEGIN
  IF NEW.number IS NOT NULL AND btrim(NEW.number) <> '' THEN RETURN NEW; END IF;
  IF NEW.status = 'draft' THEN RETURN NEW; END IF;

  year_part := to_char(COALESCE(NEW.issue_date, CURRENT_DATE), 'YYYY');
  SELECT COALESCE(MAX(NULLIF(regexp_replace(number, '^INV-' || year_part || '-', ''), '')::int), 0) + 1
    INTO next_num
    FROM academy.billing_invoices
   WHERE tenant_id = NEW.tenant_id
     AND number ~ ('^INV-' || year_part || '-[0-9]+$');

  LOOP
    candidate := 'INV-' || year_part || '-' || lpad(next_num::text, 5, '0');
    EXIT WHEN NOT EXISTS (
      SELECT 1 FROM academy.billing_invoices
      WHERE tenant_id = NEW.tenant_id AND number = candidate
    );
    next_num := next_num + 1;
  END LOOP;
  NEW.number := candidate;
  RETURN NEW;
END; $_$;


--
-- Name: assign_match_slug(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.assign_match_slug() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
  ta_slug text; tb_slug text; base text; candidate text; suffix int := 0;
BEGIN
  IF NEW.public_slug IS NOT NULL AND btrim(NEW.public_slug) <> '' THEN RETURN NEW; END IF;
  SELECT COALESCE(NULLIF(academy.slugify(short_name), ''), NULLIF(academy.slugify(name), ''), 'team-a')
    INTO ta_slug FROM academy.mc_teams WHERE id = NEW.team_a_id;
  SELECT COALESCE(NULLIF(academy.slugify(short_name), ''), NULLIF(academy.slugify(name), ''), 'team-b')
    INTO tb_slug FROM academy.mc_teams WHERE id = NEW.team_b_id;
  base := ta_slug || '-vs-' || tb_slug
        || COALESCE('-' || to_char(NEW.scheduled_date, 'YYYYMMDD'), '')
        || '-' || substr(NEW.id::text, 1, 6);
  candidate := base;
  WHILE EXISTS(SELECT 1 FROM academy.mc_matches WHERE public_slug = candidate) LOOP
    suffix := suffix + 1;
    candidate := base || '-' || suffix::text;
  END LOOP;
  NEW.public_slug := candidate;
  RETURN NEW;
END; $$;


--
-- Name: assign_player_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.assign_player_id() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $_$
DECLARE
  prefix text;
  next_num int;
  candidate text;
BEGIN
  IF NEW.player_id IS NOT NULL AND btrim(NEW.player_id) <> '' THEN
    RETURN NEW;
  END IF;

  prefix := academy.compute_player_prefix(NEW.tenant_id);

  SELECT COALESCE(
    MAX(NULLIF(regexp_replace(player_id, '^' || prefix, ''), '')::int),
    0
  ) + 1
  INTO next_num
  FROM academy.students
  WHERE tenant_id = NEW.tenant_id
    AND player_id ~ ('^' || prefix || '[0-9]{1,4}$');

  IF next_num < 1 THEN next_num := 1; END IF;

  LOOP
    candidate := prefix || lpad(next_num::text, 4, '0');
    EXIT WHEN NOT EXISTS (
      SELECT 1 FROM academy.students
      WHERE tenant_id = NEW.tenant_id AND player_id = candidate
    );
    next_num := next_num + 1;
  END LOOP;

  NEW.player_id := candidate;
  RETURN NEW;
END;
$_$;


--
-- Name: assign_student_slug(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.assign_student_slug() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE base text; candidate text; suffix int := 0;
BEGIN
  IF NEW.public_slug IS NOT NULL AND btrim(NEW.public_slug) <> '' THEN RETURN NEW; END IF;
  base := COALESCE(NULLIF(academy.slugify(NEW.name), ''), 'player')
       || CASE WHEN NEW.player_id IS NOT NULL AND btrim(NEW.player_id) <> ''
               THEN '-' || lower(NEW.player_id)
               ELSE '-' || substr(NEW.id::text, 1, 6) END;
  candidate := base;
  WHILE EXISTS(SELECT 1 FROM academy.students WHERE public_slug = candidate) LOOP
    suffix := suffix + 1;
    candidate := base || '-' || suffix::text;
  END LOOP;
  NEW.public_slug := candidate;
  RETURN NEW;
END; $$;


