--
-- Name: attach_applicant_to_registration(uuid, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.attach_applicant_to_registration(_registration_id uuid, _email text DEFAULT NULL::text, _address text DEFAULT NULL::text, _gender text DEFAULT NULL::text, _medical_notes text DEFAULT NULL::text, _documents jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _existing uuid;
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT applicant_user_id INTO _existing
    FROM academy.registrations
   WHERE id = _registration_id;

  IF _existing IS NOT NULL AND _existing <> _uid THEN
    RAISE EXCEPTION 'Registration already linked to another applicant';
  END IF;

  UPDATE academy.registrations
     SET applicant_user_id = _uid,
         email = COALESCE(NULLIF(btrim(_email), ''), email),
         address = COALESCE(NULLIF(btrim(_address), ''), address),
         gender = COALESCE(NULLIF(_gender, ''), gender),
         medical_notes = COALESCE(NULLIF(btrim(_medical_notes), ''), medical_notes),
         documents = COALESCE(_documents, documents)
   WHERE id = _registration_id;
END; $$;


--
-- Name: attach_payment_ref(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.attach_payment_ref(_registration_id uuid, _payment_ref text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
BEGIN
  IF _payment_ref IS NULL OR btrim(_payment_ref) = '' THEN
    RAISE EXCEPTION 'Payment reference is required';
  END IF;

  UPDATE academy.registrations
     SET payment_ref = btrim(_payment_ref)
   WHERE id = _registration_id
     AND status = 'new'
     AND payment_status = 'pending'
     AND payment_ref IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Registration not found or already processed';
  END IF;
END;
$$;


--
-- Name: attendance_marks_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.attendance_marks_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'academy'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.check_out_at IS NOT NULL AND NEW.check_in_at IS NOT NULL AND NEW.check_out_at <= NEW.check_in_at THEN
      RAISE EXCEPTION 'Check-out must be after check-in';
    END IF;
    IF NEW.source = 'correction' AND NEW.corrects_id IS NULL THEN
      RAISE EXCEPTION 'Correction rows must reference the record they correct';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.session_id IS DISTINCT FROM OLD.session_id
   OR NEW.student_id IS DISTINCT FROM OLD.student_id
   OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
   OR NEW.source IS DISTINCT FROM OLD.source
   OR NEW.corrects_id IS DISTINCT FROM OLD.corrects_id
   OR NEW.check_in_at IS DISTINCT FROM OLD.check_in_at
   OR NEW.check_in_meta IS DISTINCT FROM OLD.check_in_meta
   OR NEW.visit_type IS DISTINCT FROM OLD.visit_type THEN
    RAISE EXCEPTION 'Attendance identity/check-in fields are immutable. Create a correction record instead.';
  END IF;

  IF (OLD.check_out_at IS NOT NULL) OR (OLD.status = 'absent') THEN
    IF NEW.check_out_at IS DISTINCT FROM OLD.check_out_at
     OR NEW.check_out_meta IS DISTINCT FROM OLD.check_out_meta
     OR NEW.status IS DISTINCT FROM OLD.status
     OR NEW.note IS DISTINCT FROM OLD.note THEN
      RAISE EXCEPTION 'Completed attendance is immutable. Create a correction record instead.';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.check_out_at IS NOT NULL AND NEW.check_in_at IS NOT NULL AND NEW.check_out_at <= NEW.check_in_at THEN
    RAISE EXCEPTION 'Check-out must be after check-in';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: auto_close_stale_attendance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.auto_close_stale_attendance() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE v_count integer := 0;
BEGIN
  WITH open_marks AS (
    SELECT m.id, m.check_in_at, ses.session_date
    FROM academy.attendance_marks m
    JOIN academy.attendance_sessions ses ON ses.id = m.session_id
    WHERE m.superseded_by IS NULL
      AND m.status = 'present'
      AND m.check_in_at IS NOT NULL
      AND m.check_out_at IS NULL
      AND ses.session_date < CURRENT_DATE
  )
  UPDATE academy.attendance_marks m
  SET check_out_at = LEAST(
        o.check_in_at + interval '2 hours',
        (o.session_date + time '23:59')::timestamptz
      ),
      check_out_meta = coalesce(m.check_out_meta, '{}'::jsonb)
        || jsonb_build_object('auto', true, 'reason', 'missed_checkout', 'closed_at', now())
  FROM open_marks o
  WHERE m.id = o.id;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


--
-- Name: auto_close_student_stale_attendance(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.auto_close_student_stale_attendance(_student_id uuid, _today date) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE v_count integer := 0;
BEGIN
  WITH open_marks AS (
    SELECT m.id, m.check_in_at, ses.session_date
    FROM academy.attendance_marks m
    JOIN academy.attendance_sessions ses ON ses.id = m.session_id
    WHERE m.student_id = _student_id
      AND m.superseded_by IS NULL
      AND m.status = 'present'
      AND m.check_in_at IS NOT NULL
      AND m.check_out_at IS NULL
      AND ses.session_date < _today
  )
  UPDATE academy.attendance_marks m
  SET check_out_at = LEAST(
        o.check_in_at + interval '2 hours',
        (o.session_date + time '23:59')::timestamptz
      ),
      check_out_meta = coalesce(m.check_out_meta, '{}'::jsonb)
        || jsonb_build_object('auto', true, 'reason', 'missed_checkout', 'closed_at', now())
  FROM open_marks o
  WHERE m.id = o.id;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


--
-- Name: automation_touch_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.automation_touch_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'academy'
    AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;


--
-- Name: billing_invoice_immutability_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.billing_invoice_immutability_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'academy'
    AS $$
BEGIN
  IF OLD.status = 'draft' THEN
    RETURN NEW;
  END IF;
  -- Once issued: financial fields frozen. Only balance/paid/status/notes may change.
  IF NEW.subtotal IS DISTINCT FROM OLD.subtotal
     OR NEW.discount_total IS DISTINCT FROM OLD.discount_total
     OR NEW.tax_total IS DISTINCT FROM OLD.tax_total
     OR NEW.total IS DISTINCT FROM OLD.total
     OR NEW.currency IS DISTINCT FROM OLD.currency
     OR NEW.number IS DISTINCT FROM OLD.number
     OR NEW.issue_date IS DISTINCT FROM OLD.issue_date
     OR NEW.issued_at IS DISTINCT FROM OLD.issued_at
     OR NEW.due_date IS DISTINCT FROM OLD.due_date
     OR NEW.period_start IS DISTINCT FROM OLD.period_start
     OR NEW.period_end IS DISTINCT FROM OLD.period_end
     OR NEW.student_id IS DISTINCT FROM OLD.student_id
     OR NEW.subscription_id IS DISTINCT FROM OLD.subscription_id
  THEN
    RAISE EXCEPTION 'Invoice % is issued and immutable. Use billing_invoice_adjustments for corrections.', OLD.id;
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: billing_invoice_line_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.billing_invoice_line_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'academy'
    AS $$
DECLARE inv_status text;
BEGIN
  SELECT status INTO inv_status FROM academy.billing_invoices
    WHERE id = COALESCE(NEW.invoice_id, OLD.invoice_id);
  IF inv_status IS DISTINCT FROM 'draft' THEN
    RAISE EXCEPTION 'Cannot modify lines on a non-draft invoice. Use an adjustment.';
  END IF;
  RETURN COALESCE(NEW, OLD);
END; $$;


--
-- Name: bulk_approve_registrations(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.bulk_approve_registrations(_tenant_id uuid, _ids uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
  reg_id uuid;
  count int := 0;
BEGIN
  IF NOT academy.is_tenant_member(auth.uid(), _tenant_id) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  FOREACH reg_id IN ARRAY _ids
  LOOP
    PERFORM academy.approve_registration(reg_id);
    count := count + 1;
  END LOOP;

  RETURN count;
END; $$;


--
-- Name: bulk_approve_registrations_v2(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.bulk_approve_registrations_v2(_tenant_id uuid, _ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
  reg_id uuid;
  new_id uuid;
  result jsonb := '[]'::jsonb;
BEGIN
  IF NOT academy.is_tenant_member(auth.uid(), _tenant_id) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  FOREACH reg_id IN ARRAY _ids
  LOOP
    BEGIN
      new_id := academy.approve_registration(reg_id);
      result := result || jsonb_build_object(
        'registration_id', reg_id,
        'student_id', new_id
      );
    EXCEPTION WHEN OTHERS THEN
      -- Skip individual failures in bulk
      RAISE NOTICE 'Failed to approve registration %: %', reg_id, SQLERRM;
    END;
  END LOOP;

  RETURN result;
END;
$$;


--
-- Name: bulk_enqueue_notification_recipients(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.bulk_enqueue_notification_recipients(_campaign_id uuid, _recipient_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
  camp record;
  n int;
BEGIN
  SELECT id, tenant_id INTO camp FROM comm_campaigns WHERE id = _campaign_id;
  IF camp.id IS NULL THEN RAISE EXCEPTION 'campaign not found'; END IF;
  IF NOT academy.is_tenant_member(auth.uid(), camp.tenant_id) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  INSERT INTO comm_campaign_recipients (campaign_id, student_id, status)
  SELECT _campaign_id, r, 'queued'
  FROM UNNEST(_recipient_ids) r
  ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END; $$;


--
-- Name: bulk_mark_attendance(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.bulk_mark_attendance(_session_id uuid, _marks jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
  sess record;
  n int := 0;
BEGIN
  SELECT id, tenant_id, batch_id INTO sess
  FROM attendance_sessions WHERE id = _session_id;
  IF sess.id IS NULL THEN RAISE EXCEPTION 'session not found'; END IF;
  IF NOT academy.is_tenant_member(auth.uid(), sess.tenant_id) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  -- Supersede prior marks for the affected students in this session
  UPDATE attendance_marks am
     SET superseded_by = gen_random_uuid()
   WHERE am.session_id = _session_id
     AND am.superseded_by IS NULL
     AND am.student_id IN (
       SELECT (elem->>'student_id')::uuid FROM jsonb_array_elements(_marks) elem
     );

  INSERT INTO attendance_marks (session_id, tenant_id, student_id, status, marked_by, remark)
  SELECT _session_id,
         sess.tenant_id,
         (elem->>'student_id')::uuid,
         (elem->>'status')::text,
         auth.uid(),
         elem->>'remark'
  FROM jsonb_array_elements(_marks) elem;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END; $$;


--
-- Name: cancel_campaign(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.cancel_campaign(_campaign_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE c academy.comm_campaigns%ROWTYPE;
BEGIN
  SELECT * INTO c FROM academy.comm_campaigns WHERE id = _campaign_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Campaign not found'; END IF;
  IF NOT (academy.is_tenant_member(auth.uid(), c.tenant_id) OR academy.is_platform_admin(auth.uid())) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  IF c.status NOT IN ('draft','scheduled') THEN
    RAISE EXCEPTION 'Only draft/scheduled campaigns can be cancelled';
  END IF;
  UPDATE academy.comm_campaigns SET status = 'cancelled' WHERE id = _campaign_id;
END; $$;


--
-- Name: check_rate_limit(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.check_rate_limit(_key text, _max_hits integer, _window_seconds integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
  win_start timestamptz := date_trunc('second', now())
     - (EXTRACT(EPOCH FROM now())::bigint % _window_seconds) * interval '1 second';
  cur_hits int;
BEGIN
  -- Garbage-collect old buckets opportunistically
  DELETE FROM academy.rate_limit_hits
    WHERE window_start < now() - interval '1 hour';

  INSERT INTO academy.rate_limit_hits(bucket_key, window_start, hits)
  VALUES (_key, win_start, 1)
  ON CONFLICT (bucket_key, window_start)
  DO UPDATE SET hits = academy.rate_limit_hits.hits + 1
  RETURNING hits INTO cur_hits;

  RETURN cur_hits <= _max_hits;
END; $$;


--
-- Name: claim_registration_payment(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.claim_registration_payment(p_registration_id uuid, p_payment_ref text) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
  UPDATE academy.registrations
  SET payment_status = 'claimed_paid',
      payment_ref = left(trim(p_payment_ref), 100)
  WHERE id = p_registration_id
    AND payment_status = 'pending'
    AND trim(coalesce(p_payment_ref, '')) <> ''
  RETURNING true;
$$;


--
-- Name: compute_player_prefix(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.compute_player_prefix(_tenant_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
  raw text;
  clean text;
BEGIN
  SELECT COALESCE(NULLIF(btrim(player_prefix), ''), name)
    INTO raw
  FROM academy.tenants WHERE id = _tenant_id;
  IF raw IS NULL THEN RETURN 'ACD'; END IF;
  clean := upper(regexp_replace(raw, '[^A-Za-z]', '', 'g'));
  IF length(clean) >= 3 THEN
    RETURN substring(clean from 1 for 3);
  ELSIF length(clean) > 0 THEN
    RETURN rpad(clean, 3, 'X');
  END IF;
  RETURN 'ACD';
END;
$$;


--
-- Name: correct_attendance(uuid, timestamp with time zone, timestamp with time zone, academy.attendance_status, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.correct_attendance(_original_id uuid, _check_in_at timestamp with time zone, _check_out_at timestamp with time zone, _status academy.attendance_status, _note text DEFAULT NULL::text, _check_in_meta jsonb DEFAULT '{}'::jsonb, _check_out_meta jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
  orig academy.attendance_marks%ROWTYPE;
  new_id uuid;
BEGIN
  SELECT * INTO orig FROM academy.attendance_marks WHERE id = _original_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Original attendance not found'; END IF;
  IF NOT (academy.is_tenant_member(auth.uid(), orig.tenant_id)
          OR academy.is_platform_admin(auth.uid())) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  IF orig.superseded_by IS NOT NULL THEN
    RAISE EXCEPTION 'Record already corrected';
  END IF;

  INSERT INTO academy.attendance_marks
    (tenant_id, session_id, student_id, status, check_in_at, check_out_at,
     source, marked_by, corrects_id, note, check_in_meta, check_out_meta)
  VALUES
    (orig.tenant_id, orig.session_id, orig.student_id, _status,
     _check_in_at, _check_out_at, 'correction', auth.uid(), _original_id,
     _note, COALESCE(_check_in_meta,'{}'::jsonb), COALESCE(_check_out_meta,'{}'::jsonb))
  RETURNING id INTO new_id;

  UPDATE academy.attendance_marks SET superseded_by = new_id WHERE id = _original_id;
  RETURN new_id;
END;
$$;


--
-- Name: correct_attendance(uuid, timestamp with time zone, timestamp with time zone, academy.attendance_status, text, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.correct_attendance(_original_id uuid, _check_in_at timestamp with time zone, _check_out_at timestamp with time zone, _status academy.attendance_status, _note text DEFAULT NULL::text, _check_in_meta jsonb DEFAULT '{}'::jsonb, _check_out_meta jsonb DEFAULT '{}'::jsonb, _visit_type text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE orig academy.attendance_marks%ROWTYPE; new_id uuid;
BEGIN
  SELECT * INTO orig FROM academy.attendance_marks WHERE id = _original_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Original attendance not found'; END IF;
  IF NOT (academy.is_tenant_member(auth.uid(), orig.tenant_id) OR academy.is_platform_admin(auth.uid())) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  IF orig.superseded_by IS NOT NULL THEN RAISE EXCEPTION 'Record already corrected'; END IF;

  INSERT INTO academy.attendance_marks
    (tenant_id, session_id, student_id, status, check_in_at, check_out_at,
     source, marked_by, corrects_id, note, check_in_meta, check_out_meta, visit_type)
  VALUES
    (orig.tenant_id, orig.session_id, orig.student_id, _status,
     _check_in_at, _check_out_at, 'correction', auth.uid(), _original_id,
     _note, COALESCE(_check_in_meta,'{}'::jsonb), COALESCE(_check_out_meta,'{}'::jsonb),
     COALESCE(_visit_type, orig.visit_type))
  RETURNING id INTO new_id;

  UPDATE academy.attendance_marks SET superseded_by = new_id WHERE id = _original_id;
  RETURN new_id;
END;
$$;


--
-- Name: create_billing_adjustment(uuid, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.create_billing_adjustment(_invoice_id uuid, _kind text, _amount numeric, _reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE inv academy.billing_invoices%ROWTYPE; adj_id uuid;
BEGIN
  SELECT * INTO inv FROM academy.billing_invoices WHERE id = _invoice_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Invoice not found'; END IF;
  IF NOT (academy.is_tenant_owner(auth.uid(), inv.tenant_id) OR academy.is_platform_admin(auth.uid())) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  IF inv.status = 'draft' THEN RAISE EXCEPTION 'Adjust only issued invoices'; END IF;

  INSERT INTO academy.billing_invoice_adjustments(tenant_id, invoice_id, kind, amount, reason, created_by)
  VALUES (inv.tenant_id, _invoice_id, _kind, _amount, _reason, auth.uid())
  RETURNING id INTO adj_id;

  -- Waivers/write-offs reduce effective balance
  IF _kind IN ('waiver','writeoff','credit_note') THEN
    UPDATE academy.billing_invoices
       SET balance = GREATEST(balance - _amount, 0),
           status = CASE
             WHEN GREATEST(balance - _amount, 0) = 0 THEN 'paid'
             ELSE status
           END
     WHERE id = _invoice_id;
  END IF;

  INSERT INTO academy.billing_audit_log(tenant_id, entity_type, entity_id, action, actor_id, metadata)
  VALUES (inv.tenant_id, 'invoice', _invoice_id, 'adjusted', auth.uid(),
          jsonb_build_object('kind', _kind, 'amount', _amount, 'reason', _reason));
  RETURN adj_id;
END; $$;


--
-- Name: current_role(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy."current_role"(_tenant_id uuid) RETURNS academy.app_role
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
  SELECT role FROM academy.user_roles
  WHERE user_id = auth.uid()
    AND (tenant_id = _tenant_id OR tenant_id IS NULL)
  ORDER BY CASE role
    WHEN 'platform_admin' THEN 0
    WHEN 'owner' THEN 1
    WHEN 'admin' THEN 2
    WHEN 'student' THEN 3
  END
  LIMIT 1;
$$;


--
-- Name: delete_all_archived_students_v2(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.delete_all_archived_students_v2(_tenant_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
    _student_id uuid;
    _count integer := 0;
BEGIN
    -- Verify caller is owner or admin
    IF NOT (
        academy.has_role(auth.uid(), _tenant_id, 'owner') OR 
        academy.has_role(auth.uid(), _tenant_id, 'admin') OR
        academy.is_platform_admin(auth.uid())
    ) THEN
        RAISE EXCEPTION 'Forbidden';
    END IF;

    FOR _student_id IN (SELECT id FROM academy.students WHERE tenant_id = _tenant_id AND status = 'left') LOOP
        PERFORM academy.delete_student_data_v2(_student_id);
        _count := _count + 1;
    END LOOP;
    
    RETURN _count;
END;
$$;


--
-- Name: delete_student_data_v2(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.delete_student_data_v2(_student_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
    _tenant_id uuid;
    _invoice_ids uuid[];
BEGIN
    -- Get tenant_id
    SELECT tenant_id INTO _tenant_id FROM academy.students WHERE id = _student_id;
    
    -- Verify caller is owner or admin for this tenant
    IF NOT (
        academy.has_role(auth.uid(), _tenant_id, 'owner') OR 
        academy.has_role(auth.uid(), _tenant_id, 'admin') OR
        academy.is_platform_admin(auth.uid())
    ) THEN
        RAISE EXCEPTION 'Forbidden';
    END IF;

    -- 1. Billing allocations
    DELETE FROM academy.billing_payment_allocations
    WHERE payment_id IN (SELECT id FROM academy.billing_payments WHERE student_id = _student_id);
    
    -- 2. Billing payments
    DELETE FROM academy.billing_payments WHERE student_id = _student_id;
    
    -- 3. Billing invoices and lines
    SELECT array_agg(id) INTO _invoice_ids FROM academy.billing_invoices WHERE student_id = _student_id;
    IF _invoice_ids IS NOT NULL THEN
        DELETE FROM academy.billing_invoice_lines WHERE invoice_id = ANY(_invoice_ids);
        DELETE FROM academy.billing_invoices WHERE id = ANY(_invoice_ids);
    END IF;
    
    -- 4. Billing charges and subs
    DELETE FROM academy.billing_charges WHERE student_id = _student_id;
    DELETE FROM academy.billing_subscriptions WHERE student_id = _student_id;
    
    -- 5. Legacy payments
    DELETE FROM academy.payments WHERE student_id = _student_id;
    
    -- 6. Student
    DELETE FROM academy.students WHERE id = _student_id;
END;
$$;


--
-- Name: geo_distance_m(double precision, double precision, double precision, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.geo_distance_m(lat1 double precision, lng1 double precision, lat2 double precision, lng2 double precision) RETURNS double precision
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'academy'
    AS $$
  SELECT 6371000 * 2 * asin(sqrt(
    power(sin(radians(lat2 - lat1) / 2), 2) +
    cos(radians(lat1)) * cos(radians(lat2)) *
    power(sin(radians(lng2 - lng1) / 2), 2)
  ));
$$;


--
-- Name: get_academy_health(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.get_academy_health(_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
  today date := (now() AT TIME ZONE 'Asia/Kolkata')::date;
  att_pct numeric; coll_pct numeric; retention_pct numeric; adm_momentum numeric; deliv_pct numeric;
  score numeric;
  result jsonb;
BEGIN
  PERFORM academy._agg_assert_tenant(_tenant_id);

  SELECT round(100.0 * count(*) FILTER (WHERE am.status IN ('present','late')) / NULLIF(count(*),0), 1)
    INTO att_pct
  FROM attendance_marks am JOIN attendance_sessions s ON s.id = am.session_id
  WHERE am.tenant_id = _tenant_id AND am.superseded_by IS NULL
    AND s.session_date >= today - 30;

  SELECT round(100.0 * SUM(amount_paid) / NULLIF(SUM(total),0), 1)
    INTO coll_pct
  FROM billing_invoices
  WHERE tenant_id = _tenant_id AND status IN ('issued','partially_paid','paid')
    AND issue_date >= today - 90;

  SELECT round(100.0 * count(*) FILTER (WHERE archived_at IS NULL) / NULLIF(count(*),0), 1)
    INTO retention_pct
  FROM students WHERE tenant_id = _tenant_id;

  SELECT round(100.0 *
    (SELECT count(*) FROM registrations WHERE tenant_id = _tenant_id AND created_at >= now() - interval '30 days')::numeric /
    NULLIF((SELECT count(*) FROM registrations WHERE tenant_id = _tenant_id AND created_at >= now() - interval '60 days' AND created_at < now() - interval '30 days'), 0)
  , 1) INTO adm_momentum;

  SELECT round(100.0 * SUM(delivered_count) / NULLIF(SUM(recipient_count),0), 1)
    INTO deliv_pct
  FROM comm_campaigns WHERE tenant_id = _tenant_id AND created_at >= now() - interval '90 days';

  score := (
    COALESCE(att_pct,0) * 0.30
    + COALESCE(coll_pct,0) * 0.30
    + COALESCE(retention_pct,0) * 0.20
    + LEAST(COALESCE(adm_momentum,0),200) * 0.10
    + COALESCE(deliv_pct,0) * 0.10
  ) / 100 * 100;

  result := jsonb_build_object(
    'score', round(score, 1),
    'attendance_pct', att_pct,
    'collection_pct', coll_pct,
    'retention_pct', retention_pct,
    'admissions_momentum_pct', adm_momentum,
    'delivery_pct', deliv_pct,
    'as_of', now()
  );
  RETURN result;
END;
$$;


--
-- Name: get_academy_records_summary(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.get_academy_records_summary(_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE result jsonb;
BEGIN
  PERFORM academy._agg_assert_tenant(_tenant_id);
  SELECT jsonb_build_object(
    'total', (SELECT count(*) FROM mc_academy_records WHERE tenant_id = _tenant_id),
    'top', COALESCE((SELECT jsonb_agg(to_jsonb(r)) FROM (
      SELECT id, record_type, title, value, holder_name, achieved_at
      FROM mc_academy_records WHERE tenant_id = _tenant_id
      ORDER BY achieved_at DESC NULLS LAST LIMIT 10
    ) r), '[]'::jsonb)
  ) INTO result;
  RETURN result;
END;
$$;


--
-- Name: get_ai_report_inputs(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.get_ai_report_inputs(_tenant_id uuid, _from date DEFAULT NULL::date, _to date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE result jsonb;
BEGIN
  PERFORM academy._agg_assert_tenant(_tenant_id);
  result := jsonb_build_object(
    'dashboard', academy.get_dashboard_summary(_tenant_id),
    'health', academy.get_academy_health(_tenant_id),
    'attendance', academy.get_attendance_summary(_tenant_id, _from, _to),
    'finance', academy.get_finance_summary(_tenant_id, _from, _to),
    'registrations', academy.get_registration_summary(_tenant_id, _from, _to),
    'communication', academy.get_communication_summary(_tenant_id, _from, _to)
  );
  RETURN result;
END;
$$;


--
-- Name: get_attendance_qr_settings(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.get_attendance_qr_settings(_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE t academy.tenants%ROWTYPE;
BEGIN
  IF NOT academy.is_tenant_member(auth.uid(), _tenant_id) THEN
    RAISE EXCEPTION 'not authorised';
  END IF;
  SELECT * INTO t FROM academy.tenants WHERE id = _tenant_id;
  RETURN jsonb_build_object(
    'enabled', coalesce(t.attendance_qr_enabled, false),
    'token', t.attendance_qr_token,
    'lat', t.geo_lat,
    'lng', t.geo_lng,
    'radius_m', coalesce(t.geo_radius_m, 150),
    'min_gap_seconds', coalesce(t.attendance_qr_min_gap_seconds, 120)
  );
END;
$$;


--
-- Name: get_attendance_summary(uuid, date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.get_attendance_summary(_tenant_id uuid, _from date DEFAULT NULL::date, _to date DEFAULT NULL::date, _batch_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
  d_from date := COALESCE(_from, (now() AT TIME ZONE 'Asia/Kolkata')::date - 30);
  d_to date := COALESCE(_to, (now() AT TIME ZONE 'Asia/Kolkata')::date);
  result jsonb;
BEGIN
  PERFORM academy._agg_assert_tenant(_tenant_id);

  WITH marks AS (
    SELECT am.*, s.session_date, s.batch_id
    FROM attendance_marks am
    JOIN attendance_sessions s ON s.id = am.session_id
    WHERE am.tenant_id = _tenant_id
      AND am.superseded_by IS NULL
      AND s.session_date BETWEEN d_from AND d_to
      AND (_batch_id IS NULL OR s.batch_id = _batch_id)
  ), by_status AS (
    SELECT status::text AS status, count(*)::int AS n FROM marks GROUP BY status
  ), trend AS (
    SELECT session_date,
      count(*) FILTER (WHERE status IN ('present','late'))::int AS present,
      count(*) FILTER (WHERE status = 'absent')::int AS absent,
      count(*)::int AS total
    FROM marks GROUP BY session_date ORDER BY session_date
  ), at_risk AS (
    SELECT m.student_id, st.name,
      count(*) FILTER (WHERE m.status = 'absent')::int AS absences,
      count(*)::int AS total,
      round(100.0 * count(*) FILTER (WHERE m.status = 'absent') / NULLIF(count(*),0), 1) AS absent_pct
    FROM marks m JOIN students st ON st.id = m.student_id
    GROUP BY m.student_id, st.name
    HAVING count(*) FILTER (WHERE m.status = 'absent') >= 3
    ORDER BY absent_pct DESC NULLS LAST
    LIMIT 10
  )
  SELECT jsonb_build_object(
    'range', jsonb_build_object('from', d_from, 'to', d_to),
    'total_marks', (SELECT count(*) FROM marks),
    'present', COALESCE((SELECT n FROM by_status WHERE status='present'),0),
    'late',    COALESCE((SELECT n FROM by_status WHERE status='late'),0),
    'absent',  COALESCE((SELECT n FROM by_status WHERE status='absent'),0),
    'excused', COALESCE((SELECT n FROM by_status WHERE status='excused'),0),
    'attendance_pct', (
      SELECT round(100.0 * count(*) FILTER (WHERE status IN ('present','late')) / NULLIF(count(*),0), 1) FROM marks
    ),
    'trend', COALESCE((SELECT jsonb_agg(jsonb_build_object('date', session_date, 'present', present, 'absent', absent, 'total', total)) FROM trend), '[]'::jsonb),
    'at_risk', COALESCE((SELECT jsonb_agg(jsonb_build_object('student_id', student_id, 'name', name, 'absences', absences, 'total', total, 'absent_pct', absent_pct)) FROM at_risk), '[]'::jsonb)
  ) INTO result;
  RETURN result;
END;
$$;


--
-- Name: get_communication_summary(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.get_communication_summary(_tenant_id uuid, _from date DEFAULT NULL::date, _to date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
  today date := (now() AT TIME ZONE 'Asia/Kolkata')::date;
  d_from date := COALESCE(_from, today - 90);
  d_to date := COALESCE(_to, today);
  result jsonb;
BEGIN
  PERFORM academy._agg_assert_tenant(_tenant_id);

  WITH camps AS (
    SELECT * FROM comm_campaigns
    WHERE tenant_id = _tenant_id AND created_at::date BETWEEN d_from AND d_to
  ), recent AS (
    SELECT id, title, category, status, recipient_count, delivered_count, failed_count, sent_at, created_at
    FROM camps ORDER BY COALESCE(sent_at, created_at) DESC LIMIT 10
  )
  SELECT jsonb_build_object(
    'range', jsonb_build_object('from', d_from, 'to', d_to),
    'total_campaigns', (SELECT count(*) FROM camps),
    'sent', (SELECT count(*) FROM camps WHERE status = 'sent'),
    'failed', (SELECT count(*) FROM camps WHERE status = 'failed'),
    'draft', (SELECT count(*) FROM camps WHERE status = 'draft'),
    'total_recipients', COALESCE((SELECT SUM(recipient_count)::int FROM camps), 0),
    'total_delivered', COALESCE((SELECT SUM(delivered_count)::int FROM camps), 0),
    'total_failed', COALESCE((SELECT SUM(failed_count)::int FROM camps), 0),
    'delivery_pct', (SELECT round(100.0 * SUM(delivered_count) / NULLIF(SUM(recipient_count),0), 1) FROM camps),
    'by_category', COALESCE((SELECT jsonb_object_agg(category, n) FROM (SELECT category, count(*)::int AS n FROM camps GROUP BY category) x), '{}'::jsonb),
    'recent', COALESCE((SELECT jsonb_agg(to_jsonb(recent)) FROM recent), '[]'::jsonb)
  ) INTO result;
  RETURN result;
END;
$$;


--
-- Name: get_dashboard_summary(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.get_dashboard_summary(_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
  today date := (now() AT TIME ZONE 'Asia/Kolkata')::date;
  month_start date := date_trunc('month', today)::date;
  week_ago timestamptz := now() - interval '7 days';
  result jsonb;
BEGIN
  PERFORM academy._agg_assert_tenant(_tenant_id);

  SELECT jsonb_build_object(
    'total_students', (SELECT count(*) FROM students WHERE tenant_id = _tenant_id AND archived_at IS NULL),
    'active_students', (SELECT count(*) FROM students WHERE tenant_id = _tenant_id AND status = 'active' AND archived_at IS NULL),
    'archived_students', (SELECT count(*) FROM students WHERE tenant_id = _tenant_id AND archived_at IS NOT NULL),
    'present_today', (
      SELECT count(DISTINCT am.student_id) FROM attendance_marks am
      JOIN attendance_sessions s ON s.id = am.session_id
      WHERE am.tenant_id = _tenant_id AND s.session_date = today
        AND am.superseded_by IS NULL AND am.status IN ('present','late')
    ),
    'absent_today', (
      SELECT count(DISTINCT am.student_id) FROM attendance_marks am
      JOIN attendance_sessions s ON s.id = am.session_id
      WHERE am.tenant_id = _tenant_id AND s.session_date = today
        AND am.superseded_by IS NULL AND am.status = 'absent'
    ),
    'sessions_today', (SELECT count(*) FROM attendance_sessions WHERE tenant_id = _tenant_id AND session_date = today),
    'pending_registrations', (SELECT count(*) FROM registrations WHERE tenant_id = _tenant_id AND status = 'new'),
    'new_registrations_7d', (SELECT count(*) FROM registrations WHERE tenant_id = _tenant_id AND created_at >= week_ago),
    'collected_this_month', (
      SELECT COALESCE(SUM(amount),0)::numeric FROM payments
      WHERE tenant_id = _tenant_id AND created_at >= month_start
    ),
    'collected_billing_this_month', (
      SELECT COALESCE(SUM(amount),0)::numeric FROM billing_payments
      WHERE tenant_id = _tenant_id AND status = 'succeeded' AND collected_at >= month_start
    ),
    'outstanding_balance', (
      SELECT COALESCE(SUM(balance),0)::numeric FROM billing_invoices
      WHERE tenant_id = _tenant_id AND status IN ('issued','partially_paid')
    ),
    'overdue_invoices', (
      SELECT count(*) FROM billing_invoices
      WHERE tenant_id = _tenant_id AND status IN ('issued','partially_paid')
        AND due_date IS NOT NULL AND due_date < today
    ),
    'live_matches', (SELECT count(*) FROM mc_matches WHERE tenant_id = _tenant_id AND status = 'live'),
    'upcoming_matches', (SELECT count(*) FROM mc_matches WHERE tenant_id = _tenant_id AND status IN ('scheduled','upcoming') AND scheduled_date >= today),
    'active_batches', (SELECT count(*) FROM batches WHERE tenant_id = _tenant_id),
    'unread_leads', (SELECT count(*) FROM leads WHERE tenant_id = _tenant_id AND status IN ('new','contacted')),
    'as_of', now()
  ) INTO result;
  RETURN result;
END;
$$;


--
-- Name: get_finance_summary(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.get_finance_summary(_tenant_id uuid, _from date DEFAULT NULL::date, _to date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
  today date := (now() AT TIME ZONE 'Asia/Kolkata')::date;
  d_from date := COALESCE(_from, today - 180);
  d_to date := COALESCE(_to, today);
  result jsonb;
BEGIN
  PERFORM academy._agg_assert_tenant(_tenant_id);

  WITH pays AS (
    SELECT amount::numeric, collected_at::date AS d
    FROM billing_payments
    WHERE tenant_id = _tenant_id AND status = 'succeeded'
      AND collected_at::date BETWEEN d_from AND d_to
    UNION ALL
    SELECT amount::numeric, created_at::date AS d
    FROM payments
    WHERE tenant_id = _tenant_id AND created_at::date BETWEEN d_from AND d_to
  ), monthly AS (
    SELECT to_char(date_trunc('month', d), 'YYYY-MM') AS month,
           SUM(amount)::numeric AS collected
    FROM pays GROUP BY 1 ORDER BY 1
  ), inv_status AS (
    SELECT status, count(*)::int AS n, COALESCE(SUM(total),0)::numeric AS total
    FROM billing_invoices WHERE tenant_id = _tenant_id
      AND issue_date BETWEEN d_from AND d_to
    GROUP BY status
  ), top_def AS (
    SELECT bi.student_id, s.name,
      COALESCE(SUM(bi.balance),0)::numeric AS outstanding,
      count(*)::int AS invoices,
      max(bi.due_date) AS latest_due
    FROM billing_invoices bi JOIN students s ON s.id = bi.student_id
    WHERE bi.tenant_id = _tenant_id AND bi.status IN ('issued','partially_paid')
    GROUP BY bi.student_id, s.name
    HAVING SUM(bi.balance) > 0
    ORDER BY outstanding DESC LIMIT 10
  )
  SELECT jsonb_build_object(
    'range', jsonb_build_object('from', d_from, 'to', d_to),
    'collected', COALESCE((SELECT SUM(amount)::numeric FROM pays), 0),
    'outstanding', COALESCE((SELECT SUM(balance) FROM billing_invoices WHERE tenant_id = _tenant_id AND status IN ('issued','partially_paid')), 0),
    'overdue_count', (SELECT count(*) FROM billing_invoices WHERE tenant_id = _tenant_id AND status IN ('issued','partially_paid') AND due_date < today),
    'overdue_amount', COALESCE((SELECT SUM(balance) FROM billing_invoices WHERE tenant_id = _tenant_id AND status IN ('issued','partially_paid') AND due_date < today), 0),
    'invoice_status', COALESCE((SELECT jsonb_object_agg(status, jsonb_build_object('count', n, 'total', total)) FROM inv_status), '{}'::jsonb),
    'trend', COALESCE((SELECT jsonb_agg(jsonb_build_object('month', month, 'collected', collected)) FROM monthly), '[]'::jsonb),
    'top_defaulters', COALESCE((SELECT jsonb_agg(jsonb_build_object('student_id', student_id, 'name', name, 'outstanding', outstanding, 'invoices', invoices, 'latest_due', latest_due)) FROM top_def), '[]'::jsonb)
  ) INTO result;
  RETURN result;
END;
$$;


--
-- Name: get_my_student_context(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.get_my_student_context() RETURNS TABLE(student_id uuid, tenant_id uuid, athlete_profile_id uuid, name text, player_id text, email text, photo_url text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
  SELECT
    s.id AS student_id,
    s.tenant_id,
    ap.id AS athlete_profile_id,
    s.name,
    s.player_id,
    s.email,
    s.photo_url
  FROM academy.students s
  LEFT JOIN academy.mc_athlete_profiles ap ON ap.student_id = s.id
  WHERE
    s.archived_at IS NULL
    AND (
      s.user_id = auth.uid()
      OR (s.email IS NOT NULL AND auth.email() IS NOT NULL
          AND lower(s.email) = lower(auth.email()))
    )
  ORDER BY s.joined_at DESC
  LIMIT 1
$$;


--
-- Name: get_parent_child_summary(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.get_parent_child_summary(_student_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
  link_ok boolean;
  ap_id uuid;
  result jsonb;
BEGIN
  SELECT EXISTS(
    SELECT 1 FROM academy.mc_parent_links
    WHERE parent_user_id = auth.uid() AND student_id = _student_id
  ) INTO link_ok;
  IF NOT link_ok AND NOT academy.is_platform_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT id INTO ap_id FROM academy.mc_athlete_profiles WHERE student_id = _student_id LIMIT 1;

  result := jsonb_build_object(
    'student', (SELECT jsonb_build_object(
        'id', s.id, 'name', s.name, 'player_id', s.player_id,
        'dob', s.dob, 'gender', s.gender, 'photo_url', s.photo_url,
        'batch_id', s.batch_id, 'tenant_id', s.tenant_id
      ) FROM academy.students s WHERE s.id = _student_id),
    'athlete_profile_id', ap_id,
    'cricket_profile', (SELECT to_jsonb(cp) FROM academy.mc_cricket_profiles cp WHERE cp.athlete_profile_id = ap_id LIMIT 1),
    'career', (SELECT to_jsonb(c) FROM academy.mc_player_careers c WHERE c.athlete_profile_id = ap_id LIMIT 1),
    'recognitions', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', r.id, 'recognition_type', r.recognition_type, 'title', r.title,
        'description', r.description, 'awarded_at', r.awarded_at, 'status', r.status,
        'badge', r.badge, 'image_url', r.image_url
      ) ORDER BY r.awarded_at DESC NULLS LAST)
      FROM academy.mc_recognitions r
      WHERE r.athlete_profile_id = ap_id AND r.status = 'published'
    ), '[]'::jsonb),
    'achievements', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', a.id, 'kind', a.kind, 'title', a.title,
        'description', a.description, 'event_date', a.event_date
      ) ORDER BY a.event_date DESC NULLS LAST)
      FROM academy.mc_athlete_achievements a
      WHERE a.athlete_profile_id = ap_id
    ), '[]'::jsonb),
    'timeline', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', t.id, 'title', t.title, 'description', t.description,
        'event_date', t.event_date, 'image_url', t.image_url
      ) ORDER BY t.event_date DESC NULLS LAST)
      FROM academy.mc_athlete_timeline t
      WHERE t.athlete_profile_id = ap_id
    ), '[]'::jsonb),
    'recent_matches', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'match_id', mm.id, 'scheduled_date', mm.scheduled_date,
        'team_a_id', mm.team_a_id, 'team_b_id', mm.team_b_id,
        'winner_team', mm.winner_team, 'result', mm.result,
        'match_locked', mm.match_locked
      ) ORDER BY mm.scheduled_date DESC NULLS LAST)
      FROM academy.mc_matches mm
      WHERE mm.id IN (
        SELECT DISTINCT sq.match_id FROM academy.mc_match_squads sq WHERE sq.athlete_profile_id = ap_id
      )
    ), '[]'::jsonb)
  );
  RETURN result;
END;
$$;


--
-- Name: get_platform_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.get_platform_stats() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE result jsonb;
BEGIN
  IF NOT academy.is_platform_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  SELECT jsonb_build_object(
    'total_tenants', (SELECT count(*) FROM academy.tenants),
    'active_tenants', (SELECT count(*) FROM academy.tenants WHERE status = 'active'),
    'suspended_tenants', (SELECT count(*) FROM academy.tenants WHERE status = 'suspended'),
    'trial_tenants', (SELECT count(*) FROM academy.tenants WHERE status = 'trial'),
    'total_students', (SELECT count(*) FROM academy.students WHERE archived_at IS NULL),
    'total_admins', (SELECT count(*) FROM academy.profiles WHERE role IN ('owner','admin','coach','staff')),
    'total_parents', (SELECT count(*) FROM academy.mc_parent_links),
    'campaigns_sent', (SELECT count(*) FROM academy.comm_campaigns WHERE status = 'sent'),
    'notifications_30d', (SELECT count(*) FROM academy.notifications WHERE created_at > now() - interval '30 days'),
    'mrr', (SELECT COALESCE(SUM(monthly_price),0) FROM academy.tenants WHERE status = 'active'),
    'mrr_collected', (SELECT COALESCE(SUM(monthly_price),0) FROM academy.tenants WHERE status = 'active' AND subscription_status = 'paid'),
    'latest_signups', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', id, 'name', name, 'slug', slug, 'created_at', created_at, 'status', status
      ) ORDER BY created_at DESC), '[]'::jsonb)
      FROM (SELECT id, name, slug, created_at, status FROM academy.tenants ORDER BY created_at DESC LIMIT 5) s
    )
  ) INTO result;
  RETURN result;
END; $$;


--
-- Name: get_points_table(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.get_points_table(_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
  _tenant_id uuid;
  result jsonb;
BEGIN
  SELECT tenant_id INTO _tenant_id FROM mc_tournaments WHERE id = _tournament_id;
  IF _tenant_id IS NULL THEN RAISE EXCEPTION 'Tournament not found'; END IF;
  PERFORM academy._agg_assert_tenant(_tenant_id);

  WITH teams AS (
    SELECT tt.team_id, t.name, t.short_name, t.logo_url
    FROM mc_tournament_teams tt JOIN mc_teams t ON t.id = tt.team_id
    WHERE tt.tournament_id = _tournament_id
  ), finalized AS (
    SELECT * FROM mc_matches
    WHERE tournament_id = _tournament_id AND match_locked = true
  ), stats AS (
    SELECT
      te.team_id, te.name, te.short_name, te.logo_url,
      count(f.*) FILTER (WHERE te.team_id IN (f.team_a_id, f.team_b_id))::int AS played,
      count(f.*) FILTER (WHERE f.winner_team = te.team_id)::int AS won,
      count(f.*) FILTER (WHERE te.team_id IN (f.team_a_id, f.team_b_id) AND f.winner_team IS NOT NULL AND f.winner_team <> te.team_id)::int AS lost,
      count(f.*) FILTER (WHERE te.team_id IN (f.team_a_id, f.team_b_id) AND f.result IN ('tie','no_result'))::int AS tied
    FROM teams te LEFT JOIN finalized f ON te.team_id IN (f.team_a_id, f.team_b_id)
    GROUP BY te.team_id, te.name, te.short_name, te.logo_url
  )
  SELECT jsonb_agg(jsonb_build_object(
    'team_id', team_id, 'name', name, 'short_name', short_name, 'logo_url', logo_url,
    'played', played, 'won', won, 'lost', lost, 'tied', tied,
    'points', won * 2 + tied
  ) ORDER BY (won * 2 + tied) DESC, won DESC, name)
  INTO result FROM stats;
  RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


--
-- Name: get_public_academy_bundle(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.get_public_academy_bundle(_slug text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
  v_tenant academy.tenants%ROWTYPE;
  v_config academy.mc_website_config%ROWTYPE;
  result JSONB;
BEGIN
  SELECT * INTO v_tenant FROM academy.tenants
    WHERE slug = _slug OR custom_domain = _slug
    LIMIT 1;

  IF v_tenant.id IS NULL THEN RETURN NULL; END IF;

  SELECT * INTO v_config FROM academy.mc_website_config WHERE tenant_id = v_tenant.id;

  result := jsonb_build_object(
    'academy', jsonb_build_object(
      'id', v_tenant.id, 'slug', v_tenant.slug,
      'name', v_tenant.name, 'custom_domain', v_tenant.custom_domain
    ),
    'config', COALESCE(to_jsonb(v_config), jsonb_build_object(
      'theme','modern','is_published',true,
      'widgets','[]'::jsonb,'hero','{}'::jsonb,'seo','{}'::jsonb
    )),
    'upcoming_matches', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', m.id, 'scheduled_date', m.scheduled_date,
        'team_a_id', m.team_a_id, 'team_b_id', m.team_b_id,
        'venue', m.ground_name, 'format', m.match_format
      ) ORDER BY m.scheduled_date ASC)
      FROM academy.mc_matches m
      WHERE m.tenant_id = v_tenant.id
        AND m.status IN ('scheduled','live')
        AND (m.scheduled_date IS NULL OR m.scheduled_date >= now() - interval '1 day')
      LIMIT 10
    ), '[]'::jsonb),
    'recent_results', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', m.id, 'scheduled_date', m.scheduled_date,
        'team_a_id', m.team_a_id, 'team_b_id', m.team_b_id,
        'result', m.result, 'winner_team', m.winner_team
      ) ORDER BY m.scheduled_date DESC)
      FROM academy.mc_matches m
      WHERE m.tenant_id = v_tenant.id AND m.status = 'finalized'
      LIMIT 10
    ), '[]'::jsonb),
    'academy_records', COALESCE((
      SELECT jsonb_agg(to_jsonb(r) ORDER BY r.record_type)
      FROM academy.mc_academy_records r WHERE r.tenant_id = v_tenant.id LIMIT 50
    ), '[]'::jsonb),
    'hall_of_fame', COALESCE((
      SELECT jsonb_agg(to_jsonb(h) ORDER BY h.created_at DESC)
      FROM academy.mc_hall_of_fame h WHERE h.tenant_id = v_tenant.id LIMIT 20
    ), '[]'::jsonb),
    'recognitions', COALESCE((
      SELECT jsonb_agg(to_jsonb(r) ORDER BY r.created_at DESC)
      FROM academy.mc_recognitions r
      WHERE r.tenant_id = v_tenant.id AND r.status = 'published' LIMIT 20
    ), '[]'::jsonb),
    'policies', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'kind', p.kind, 'version', p.version, 'title', p.title,
        'body_md', p.body_md, 'published_at', p.published_at
      ) ORDER BY p.kind)
      FROM academy.policy_documents p
      WHERE p.tenant_id = v_tenant.id
        AND p.is_published = true
        AND p.version = (
          SELECT MAX(p2.version) FROM academy.policy_documents p2
          WHERE p2.tenant_id = p.tenant_id AND p2.kind = p.kind AND p2.is_published = true
        )
    ), '[]'::jsonb)
  );
  RETURN result;
END;
$$;


--
-- Name: get_public_match_bundle(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.get_public_match_bundle(_slug text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
  pm academy.mc_public_matches%ROWTYPE;
  m academy.mc_matches%ROWTYPE;
  result jsonb;
BEGIN
  SELECT * INTO pm FROM academy.mc_public_matches WHERE public_slug = _slug AND is_public = true;
  IF NOT FOUND THEN RETURN NULL; END IF;
  SELECT * INTO m FROM academy.mc_matches WHERE id = pm.match_id;
  IF NOT FOUND THEN RETURN NULL; END IF;

  result := jsonb_build_object(
    'public', to_jsonb(pm),
    'match', jsonb_build_object(
      'id', m.id,
      'match_type', m.match_type,
      'match_format', m.match_format,
      'overs', m.overs,
      'scheduled_date', m.scheduled_date,
      'scheduled_time', m.scheduled_time,
      'status', m.status,
      'ground_name', m.ground_name,
      'winner_team', m.winner_team,
      'result', m.result,
      'winning_margin', m.winning_margin,
      'winning_margin_type', m.winning_margin_type,
      'victory_type', m.victory_type,
      'player_of_match_athlete_id', m.player_of_match_athlete_id,
      'match_locked', m.match_locked,
      'team_a_id', m.team_a_id,
      'team_b_id', m.team_b_id,
      'toss_winner', m.toss_winner,
      'toss_decision', m.toss_decision
    ),
    'teams', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name, 'short_name', t.short_name, 'logo_url', t.logo_url))
      FROM academy.mc_teams t WHERE t.id IN (m.team_a_id, m.team_b_id)
    ), '[]'::jsonb),
    'innings', CASE WHEN pm.allow_scorecard OR pm.allow_live_score THEN
      COALESCE((SELECT jsonb_agg(to_jsonb(i) ORDER BY i.innings_number) FROM academy.mc_innings i WHERE i.match_id = m.id), '[]'::jsonb)
      ELSE '[]'::jsonb END,
    'ball_events', CASE WHEN pm.allow_live_score OR pm.allow_scorecard THEN
      COALESCE((SELECT jsonb_agg(to_jsonb(b) ORDER BY b.created_at) FROM academy.mc_ball_events b WHERE b.match_id = m.id), '[]'::jsonb)
      ELSE '[]'::jsonb END,
    'squads', CASE WHEN pm.allow_player_profiles OR pm.allow_scorecard THEN
      COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'athlete_profile_id', s.athlete_profile_id,
          'team_id', s.team_id,
          'is_captain', s.is_captain,
          'is_wicketkeeper', s.is_wicketkeeper,
          'batting_order', s.batting_order,
          'name', st.name
        ))
        FROM academy.mc_match_squads s
        LEFT JOIN academy.mc_athlete_profiles ap ON ap.id = s.athlete_profile_id
        LEFT JOIN academy.students st ON st.id = ap.student_id
        WHERE s.match_id = m.id
      ), '[]'::jsonb)
      ELSE '[]'::jsonb END,
    'pom_name', (
      SELECT st.name FROM academy.mc_athlete_profiles ap
      LEFT JOIN academy.students st ON st.id = ap.student_id
      WHERE ap.id = m.player_of_match_athlete_id
    )
  );
  RETURN result;
END;
$$;


--
-- Name: get_registration_summary(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.get_registration_summary(_tenant_id uuid, _from date DEFAULT NULL::date, _to date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
  today date := (now() AT TIME ZONE 'Asia/Kolkata')::date;
  d_from date := COALESCE(_from, today - 90);
  d_to date := COALESCE(_to, today);
  result jsonb;
BEGIN
  PERFORM academy._agg_assert_tenant(_tenant_id);

  WITH regs AS (
    SELECT * FROM registrations
    WHERE tenant_id = _tenant_id AND created_at::date BETWEEN d_from AND d_to
  ), by_status AS (
    SELECT status, count(*)::int AS n FROM regs GROUP BY status
  ), by_source AS (
    SELECT COALESCE(source, 'unknown') AS source, count(*)::int AS n FROM regs GROUP BY 1
  ), weekly AS (
    SELECT to_char(date_trunc('week', created_at), 'YYYY-"W"IW') AS wk,
           count(*)::int AS n
    FROM regs GROUP BY 1 ORDER BY 1
  )
  SELECT jsonb_build_object(
    'range', jsonb_build_object('from', d_from, 'to', d_to),
    'total', (SELECT count(*) FROM regs),
    'pending', (SELECT count(*) FROM regs WHERE status = 'new'),
    'approved', (SELECT count(*) FROM regs WHERE status = 'approved'),
    'rejected', (SELECT count(*) FROM regs WHERE status = 'rejected'),
    'conversion_pct', (SELECT round(100.0 * count(*) FILTER (WHERE status='approved') / NULLIF(count(*),0), 1) FROM regs),
    'by_status', COALESCE((SELECT jsonb_object_agg(status, n) FROM by_status), '{}'::jsonb),
    'by_source', COALESCE((SELECT jsonb_object_agg(source, n) FROM by_source), '{}'::jsonb),
    'trend', COALESCE((SELECT jsonb_agg(jsonb_build_object('week', wk, 'count', n)) FROM weekly), '[]'::jsonb)
  ) INTO result;
  RETURN result;
END;
$$;


--
-- Name: get_report_admissions(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.get_report_admissions(_tenant_id uuid, _from timestamp with time zone, _to timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE result jsonb;
BEGIN
  PERFORM academy._agg_assert_tenant(_tenant_id);
  WITH leads_r AS (
    SELECT id, source, pipeline_stage, created_at
    FROM leads
    WHERE tenant_id = _tenant_id AND created_at BETWEEN _from AND _to
  ), by_stage AS (
    SELECT COALESCE(pipeline_stage,'new') AS stage, count(*)::int AS count
    FROM leads_r GROUP BY 1
  ), by_source AS (
    SELECT COALESCE(NULLIF(source,''),'manual') AS label, count(*)::int AS count
    FROM leads_r GROUP BY 1 ORDER BY 2 DESC
  ), totals AS (
    SELECT
      count(*)::int AS total_leads,
      count(*) FILTER (WHERE pipeline_stage IN ('trial','decision','approved','converted'))::int AS trials,
      count(*) FILTER (WHERE pipeline_stage = 'converted')::int AS converted,
      count(*) FILTER (WHERE pipeline_stage = 'rejected')::int AS rejected
    FROM leads_r
  ), conv_times AS (
    SELECT EXTRACT(EPOCH FROM (t.created_at - l.created_at))/86400.0 AS days
    FROM leads_r l
    JOIN admission_timeline t ON t.lead_id = l.id AND t.to_stage = 'converted'
    WHERE l.pipeline_stage = 'converted'
  )
  SELECT jsonb_build_object(
    'totalLeads', (SELECT total_leads FROM totals),
    'byStage',    COALESCE((SELECT jsonb_agg(jsonb_build_object('stage', stage, 'count', count)) FROM by_stage), '[]'::jsonb),
    'bySource',   COALESCE((SELECT jsonb_agg(jsonb_build_object('label', label, 'count', count)) FROM by_source), '[]'::jsonb),
    'conversion', CASE WHEN (SELECT total_leads FROM totals) > 0
                       THEN round(100.0 * (SELECT converted FROM totals) / (SELECT total_leads FROM totals))::int
                       ELSE 0 END,
    'avgConversionDays', (SELECT round((AVG(days))::numeric, 1) FROM conv_times WHERE days >= 0),
    'trials',    (SELECT trials    FROM totals),
    'converted', (SELECT converted FROM totals),
    'rejected',  (SELECT rejected  FROM totals)
  ) INTO result;
  RETURN result;
END; $$;


--
-- Name: get_report_attendance(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.get_report_attendance(_tenant_id uuid, _from timestamp with time zone, _to timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
  d_from date := (_from AT TIME ZONE 'UTC')::date;
  d_to   date := (_to   AT TIME ZONE 'UTC')::date;
  result jsonb;
BEGIN
  PERFORM academy._agg_assert_tenant(_tenant_id);

  WITH sess AS (
    SELECT s.id, s.session_date, s.batch_id, COALESCE(b.name,'Unassigned') AS batch_name
    FROM attendance_sessions s
    LEFT JOIN batches b ON b.id = s.batch_id
    WHERE s.tenant_id = _tenant_id
      AND s.session_date BETWEEN d_from AND d_to
  ), marks AS (
    SELECT m.status, m.student_id, se.session_date, se.batch_name,
           st.name AS student_name
    FROM attendance_marks m
    JOIN sess se ON se.id = m.session_id
    LEFT JOIN students st ON st.id = m.student_id
    WHERE m.tenant_id = _tenant_id
      AND m.superseded_by IS NULL
      AND m.created_at BETWEEN _from AND _to
  ), totals AS (
    SELECT
      count(*)::int AS total_marks,
      count(*) FILTER (WHERE status IN ('present','late'))::int AS present,
      count(*) FILTER (WHERE status = 'absent')::int AS absent,
      count(*) FILTER (WHERE status = 'late')::int AS late
    FROM marks
  ), daily AS (
    SELECT session_date::text AS date,
      count(*) FILTER (WHERE status IN ('present','late'))::int AS present,
      count(*) FILTER (WHERE status = 'absent')::int AS absent
    FROM marks GROUP BY session_date ORDER BY session_date
  ), per_batch AS (
    SELECT batch_name AS batch,
      count(*) FILTER (WHERE status IN ('present','late'))::int AS present,
      count(*) FILTER (WHERE status IN ('present','late','absent'))::int AS total
    FROM marks GROUP BY batch_name
  ), per_student AS (
    SELECT student_id, COALESCE(student_name,'—') AS name,
      count(*) FILTER (WHERE status IN ('present','late'))::int AS present,
      count(*) FILTER (WHERE status IN ('present','late','absent'))::int AS total
    FROM marks GROUP BY student_id, student_name
    HAVING count(*) FILTER (WHERE status IN ('present','late','absent')) >= 3
  ), top_students AS (
    SELECT name, present, total,
      round(100.0 * present / NULLIF(total,0))::int AS percent
    FROM per_student
    ORDER BY (1.0 * present / NULLIF(total,0)) DESC NULLS LAST, name
    LIMIT 10
  ), low_students AS (
    SELECT name, present, total,
      round(100.0 * present / NULLIF(total,0))::int AS percent
    FROM per_student
    ORDER BY (1.0 * present / NULLIF(total,0)) ASC NULLS LAST, name
    LIMIT 10
  )
  SELECT jsonb_build_object(
    'totalMarks', (SELECT total_marks FROM totals),
    'present', (SELECT present FROM totals),
    'absent',  (SELECT absent  FROM totals),
    'late',    (SELECT late    FROM totals),
    'percent', COALESCE((SELECT round(100.0 * present / NULLIF(present + absent,0))::int FROM totals), 0),
    'sessions', (SELECT count(*)::int FROM sess),
    'daily', COALESCE((SELECT jsonb_agg(jsonb_build_object(
       'date', date, 'present', present, 'absent', absent,
       'percent', CASE WHEN present+absent > 0 THEN round(100.0 * present / (present+absent))::int ELSE 0 END
    )) FROM daily), '[]'::jsonb),
    'perBatch', COALESCE((SELECT jsonb_agg(jsonb_build_object(
       'batch', batch, 'present', present, 'total', total,
       'percent', CASE WHEN total > 0 THEN round(100.0 * present / total)::int ELSE 0 END
    ) ORDER BY (CASE WHEN total>0 THEN 1.0*present/total ELSE 0 END) DESC) FROM per_batch), '[]'::jsonb),
    'topStudents', COALESCE((SELECT jsonb_agg(to_jsonb(top_students)) FROM top_students), '[]'::jsonb),
    'lowStudents', COALESCE((SELECT jsonb_agg(to_jsonb(low_students)) FROM low_students), '[]'::jsonb)
  ) INTO result;
  RETURN result;
END; $$;


--
-- Name: get_report_billing(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.get_report_billing(_tenant_id uuid, _from timestamp with time zone, _to timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
  cur_period text := to_char(now() AT TIME ZONE 'Asia/Kolkata', 'YYYY-MM');
  result jsonb;
BEGIN
  PERFORM academy._agg_assert_tenant(_tenant_id);

  WITH pays AS (
    SELECT amount::numeric AS amount, type::text, method::text, created_at
    FROM payments
    WHERE tenant_id = _tenant_id AND created_at BETWEEN _from AND _to
  ), totals AS (
    SELECT COALESCE(SUM(amount),0)::numeric AS revenue, count(*)::int AS n FROM pays
  ), by_month AS (
    SELECT to_char(date_trunc('month', created_at), 'YYYY-MM') AS ym,
           to_char(date_trunc('month', created_at), 'Mon') AS label,
           SUM(amount)::numeric AS amount
    FROM pays GROUP BY 1,2 ORDER BY 1
  ), by_method AS (
    SELECT UPPER(COALESCE(method,'other')) AS label, SUM(amount)::numeric AS amount
    FROM pays GROUP BY 1 ORDER BY 2 DESC
  ), by_type AS (
    SELECT CASE type
             WHEN 'monthly' THEN 'Monthly fees'
             WHEN 'registration' THEN 'Registration'
             WHEN 'personal_coaching' THEN 'Personal coaching'
             ELSE 'Other' END AS label,
           SUM(amount)::numeric AS amount
    FROM pays GROUP BY 1 ORDER BY 2 DESC
  ), paid_this_period AS (
    SELECT DISTINCT student_id FROM payments
    WHERE tenant_id = _tenant_id AND period = cur_period
  ), pending AS (
    SELECT s.id, COALESCE(fp.amount,0)::numeric AS plan_amount
    FROM students s
    LEFT JOIN fee_plans fp ON fp.id = s.fee_plan_id
    WHERE s.tenant_id = _tenant_id AND s.status = 'active'
      AND s.id NOT IN (SELECT student_id FROM paid_this_period WHERE student_id IS NOT NULL)
  )
  SELECT jsonb_build_object(
    'revenue', (SELECT revenue FROM totals),
    'paymentsCount', (SELECT n FROM totals),
    'avgPayment', CASE WHEN (SELECT n FROM totals) > 0
                       THEN round((SELECT revenue FROM totals) / (SELECT n FROM totals))::int ELSE 0 END,
    'byMonth', COALESCE((SELECT jsonb_agg(jsonb_build_object('label', label, 'amount', amount)) FROM by_month), '[]'::jsonb),
    'byMethod', COALESCE((SELECT jsonb_agg(jsonb_build_object('label', label, 'amount', amount)) FROM by_method), '[]'::jsonb),
    'byType', COALESCE((SELECT jsonb_agg(jsonb_build_object('label', label, 'amount', amount)) FROM by_type), '[]'::jsonb),
    'pendingStudents', (SELECT count(*)::int FROM pending),
    'pendingApprox',   COALESCE((SELECT SUM(plan_amount)::numeric FROM pending), 0),
    'collectionRate', CASE
      WHEN (SELECT revenue FROM totals) + COALESCE((SELECT SUM(plan_amount) FROM pending),0) > 0
      THEN round(100.0 * (SELECT revenue FROM totals) /
                 ((SELECT revenue FROM totals) + COALESCE((SELECT SUM(plan_amount) FROM pending),0)))::int
      ELSE 100 END
  ) INTO result;
  RETURN result;
END; $$;


--
-- Name: get_report_matches(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.get_report_matches(_tenant_id uuid, _from timestamp with time zone, _to timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
  d_from date := (_from AT TIME ZONE 'UTC')::date;
  d_to   date := (_to   AT TIME ZONE 'UTC')::date;
  result jsonb;
BEGIN
  PERFORM academy._agg_assert_tenant(_tenant_id);
  WITH m AS (
    SELECT status::text AS status, result::text AS result
    FROM mc_matches
    WHERE tenant_id = _tenant_id
      AND scheduled_date BETWEEN d_from AND d_to
  ), buckets AS (
    SELECT
      count(*)::int AS total,
      count(*) FILTER (WHERE status = 'completed')::int AS completed,
      count(*) FILTER (WHERE status = 'live')::int AS live,
      count(*) FILTER (WHERE status IN ('scheduled','upcoming'))::int AS upcoming
    FROM m
  ), by_result AS (
    SELECT COALESCE(result, status, 'unknown') AS label, count(*)::int AS count
    FROM m GROUP BY 1 ORDER BY 2 DESC
  )
  SELECT jsonb_build_object(
    'total',     (SELECT total FROM buckets),
    'completed', (SELECT completed FROM buckets),
    'upcoming',  (SELECT upcoming FROM buckets),
    'live',      (SELECT live FROM buckets),
    'byResult',  COALESCE((SELECT jsonb_agg(jsonb_build_object('label', label, 'count', count)) FROM by_result), '[]'::jsonb),
    'topScorers','[]'::jsonb
  ) INTO result;
  RETURN result;
END; $$;


--
-- Name: get_report_players(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.get_report_players(_tenant_id uuid, _from timestamp with time zone, _to timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE result jsonb;
BEGIN
  PERFORM academy._agg_assert_tenant(_tenant_id);
  WITH s AS (
    SELECT st.id, st.status, st.dob, st.playing_role, st.created_at,
           COALESCE(b.name,'Unassigned') AS batch_name
    FROM students st
    LEFT JOIN batches b ON b.id = st.batch_id
    WHERE st.tenant_id = _tenant_id
  ), totals AS (
    SELECT
      count(*) FILTER (WHERE status = 'active')::int AS active,
      count(*) FILTER (WHERE status = 'inactive')::int AS inactive,
      count(*) FILTER (WHERE status = 'graduated')::int AS graduated,
      count(*) FILTER (WHERE created_at BETWEEN _from AND _to)::int AS new_in_range
    FROM s
  ), by_batch AS (
    SELECT batch_name AS label, count(*)::int AS count FROM s GROUP BY 1 ORDER BY 2 DESC
  ), by_role AS (
    SELECT COALESCE(playing_role::text,'unspecified') AS label, count(*)::int AS count
    FROM s GROUP BY 1 ORDER BY 2 DESC
  ), by_age AS (
    SELECT CASE
             WHEN age_years < 8  THEN 'Under 8'
             WHEN age_years < 12 THEN '8–11'
             WHEN age_years < 15 THEN '12–14'
             WHEN age_years < 18 THEN '15–17'
             ELSE '18+'
           END AS label,
           count(*)::int AS count
    FROM (
      SELECT FLOOR(EXTRACT(EPOCH FROM (now() - dob))/(365.25*86400))::int AS age_years
      FROM s WHERE dob IS NOT NULL
    ) a
    GROUP BY 1
  )
  SELECT jsonb_build_object(
    'active',    (SELECT active FROM totals),
    'inactive',  (SELECT inactive FROM totals),
    'graduated', (SELECT graduated FROM totals),
    'newInRange',(SELECT new_in_range FROM totals),
    'byBatch',   COALESCE((SELECT jsonb_agg(jsonb_build_object('label', label, 'count', count)) FROM by_batch), '[]'::jsonb),
    'byAgeGroup',COALESCE((SELECT jsonb_agg(jsonb_build_object('label', label, 'count', count)) FROM by_age), '[]'::jsonb),
    'byRole',    COALESCE((SELECT jsonb_agg(jsonb_build_object('label', label, 'count', count)) FROM by_role), '[]'::jsonb),
    'retention', CASE
      WHEN (SELECT active+inactive+graduated FROM totals) > 0
      THEN round(100.0 * (SELECT active FROM totals) / (SELECT active+inactive+graduated FROM totals))::int
      ELSE 0 END
  ) INTO result;
  RETURN result;
END; $$;


--
-- Name: get_report_website(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.get_report_website(_tenant_id uuid, _from timestamp with time zone, _to timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE result jsonb;
BEGIN
  PERFORM academy._agg_assert_tenant(_tenant_id);
  WITH regs AS (
    SELECT id FROM registrations
    WHERE tenant_id = _tenant_id AND created_at BETWEEN _from AND _to
  ), ld AS (
    SELECT COALESCE(NULLIF(source,''),'website') AS label
    FROM leads WHERE tenant_id = _tenant_id AND created_at BETWEEN _from AND _to
  ), by_source AS (
    SELECT label, count(*)::int AS count FROM ld GROUP BY 1 ORDER BY 2 DESC
  )
  SELECT jsonb_build_object(
    'webRegistrations', (SELECT count(*)::int FROM regs),
    'webLeads',         (SELECT count(*)::int FROM ld),
    'bySource', COALESCE((SELECT jsonb_agg(jsonb_build_object('label', label, 'count', count)) FROM by_source), '[]'::jsonb)
  ) INTO result;
  RETURN result;
END; $$;


--
-- Name: get_students_summary(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.get_students_summary(_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE result jsonb;
BEGIN
  PERFORM academy._agg_assert_tenant(_tenant_id);

  WITH s AS (
    SELECT * FROM students WHERE tenant_id = _tenant_id
  ), by_status AS (
    SELECT COALESCE(status,'unknown') AS k, count(*)::int AS n FROM s WHERE archived_at IS NULL GROUP BY 1
  ), by_gender AS (
    SELECT COALESCE(gender,'unknown') AS k, count(*)::int AS n FROM s WHERE archived_at IS NULL GROUP BY 1
  ), by_batch AS (
    SELECT COALESCE(b.name, 'Unassigned') AS name, count(*)::int AS n
    FROM s LEFT JOIN batches b ON b.id = s.batch_id
    WHERE s.archived_at IS NULL GROUP BY b.name ORDER BY n DESC
  ), age_buckets AS (
    SELECT
      count(*) FILTER (WHERE date_part('year', age(dob)) < 10)::int AS u10,
      count(*) FILTER (WHERE date_part('year', age(dob)) BETWEEN 10 AND 12)::int AS a10_12,
      count(*) FILTER (WHERE date_part('year', age(dob)) BETWEEN 13 AND 15)::int AS a13_15,
      count(*) FILTER (WHERE date_part('year', age(dob)) BETWEEN 16 AND 18)::int AS a16_18,
      count(*) FILTER (WHERE date_part('year', age(dob)) > 18)::int AS a18p
    FROM s WHERE archived_at IS NULL AND dob IS NOT NULL
  ), joined_trend AS (
    SELECT to_char(date_trunc('month', joined_at), 'YYYY-MM') AS month, count(*)::int AS n
    FROM s WHERE joined_at >= (now() - interval '12 months') GROUP BY 1 ORDER BY 1
  )
  SELECT jsonb_build_object(
    'total', (SELECT count(*) FROM s WHERE archived_at IS NULL),
    'archived', (SELECT count(*) FROM s WHERE archived_at IS NOT NULL),
    'by_status', COALESCE((SELECT jsonb_object_agg(k, n) FROM by_status), '{}'::jsonb),
    'by_gender', COALESCE((SELECT jsonb_object_agg(k, n) FROM by_gender), '{}'::jsonb),
    'by_batch', COALESCE((SELECT jsonb_agg(jsonb_build_object('name', name, 'count', n)) FROM by_batch), '[]'::jsonb),
    'age_buckets', COALESCE((SELECT to_jsonb(age_buckets) FROM age_buckets), '{}'::jsonb),
    'joined_trend', COALESCE((SELECT jsonb_agg(jsonb_build_object('month', month, 'count', n)) FROM joined_trend), '[]'::jsonb)
  ) INTO result;
  RETURN result;
END;
$$;


--
-- Name: get_top_performers(uuid, text, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.get_top_performers(_tenant_id uuid, _kind text DEFAULT 'batting'::text, _limit integer DEFAULT 10, _tournament_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE result jsonb;
BEGIN
  PERFORM academy._agg_assert_tenant(_tenant_id);

  IF _kind = 'batting' THEN
    SELECT jsonb_agg(row_to_json(x) ORDER BY x.runs DESC NULLS LAST) INTO result FROM (
      SELECT c.athlete_profile_id, st.name,
             c.total_runs AS runs, c.matches_played AS matches,
             c.highest_score, c.batting_average AS average, c.strike_rate
      FROM mc_player_careers c
      JOIN mc_athlete_profiles ap ON ap.id = c.athlete_profile_id
      JOIN students st ON st.id = ap.student_id
      WHERE c.tenant_id = _tenant_id
      ORDER BY c.total_runs DESC NULLS LAST
      LIMIT _limit
    ) x;
  ELSIF _kind = 'bowling' THEN
    SELECT jsonb_agg(row_to_json(x) ORDER BY x.wickets DESC NULLS LAST) INTO result FROM (
      SELECT c.athlete_profile_id, st.name,
             c.total_wickets AS wickets, c.matches_played AS matches,
             c.best_bowling, c.bowling_average AS average, c.economy_rate
      FROM mc_player_careers c
      JOIN mc_athlete_profiles ap ON ap.id = c.athlete_profile_id
      JOIN students st ON st.id = ap.student_id
      WHERE c.tenant_id = _tenant_id
      ORDER BY c.total_wickets DESC NULLS LAST
      LIMIT _limit
    ) x;
  ELSE
    result := '[]'::jsonb;
  END IF;
  RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


--
-- Name: get_tournament_summary(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.get_tournament_summary(_tenant_id uuid, _tournament_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE result jsonb;
BEGIN
  PERFORM academy._agg_assert_tenant(_tenant_id);

  WITH m AS (
    SELECT * FROM mc_matches
    WHERE tenant_id = _tenant_id
      AND (_tournament_id IS NULL OR tournament_id = _tournament_id)
  )
  SELECT jsonb_build_object(
    'total', (SELECT count(*) FROM m),
    'completed', (SELECT count(*) FROM m WHERE match_locked = true),
    'live', (SELECT count(*) FROM m WHERE status = 'live'),
    'upcoming', (SELECT count(*) FROM m WHERE status IN ('scheduled','upcoming')),
    'by_status', COALESCE((SELECT jsonb_object_agg(status, n) FROM (SELECT status, count(*)::int n FROM m GROUP BY status) s), '{}'::jsonb)
  ) INTO result;
  RETURN result;
END;
$$;


