  );
$$;


--
-- Name: increment_feature_usage(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.increment_feature_usage(_tenant_id uuid, _feature_id text, _delta integer DEFAULT 1) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
  _is_member boolean;
BEGIN
  IF _delta = 0 THEN RETURN; END IF;

  SELECT EXISTS (
    SELECT 1 FROM academy.profiles WHERE id = auth.uid() AND tenant_id = _tenant_id
  ) OR academy.is_platform_admin(auth.uid())
  INTO _is_member;

  IF NOT _is_member THEN
    RAISE EXCEPTION 'not a tenant member';
  END IF;

  INSERT INTO academy.feature_usage (tenant_id, feature_id, period_start, count)
  VALUES (_tenant_id, _feature_id, date_trunc('month', now())::date, GREATEST(_delta, 0))
  ON CONFLICT (tenant_id, feature_id, period_start)
  DO UPDATE SET count = academy.feature_usage.count + EXCLUDED.count,
                updated_at = now();
END;
$$;


