--
-- Name: issue_billing_invoice(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.issue_billing_invoice(_invoice_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE inv academy.billing_invoices%ROWTYPE;
BEGIN
  SELECT * INTO inv FROM academy.billing_invoices WHERE id = _invoice_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Invoice not found'; END IF;
  IF NOT (academy.is_tenant_owner(auth.uid(), inv.tenant_id) OR academy.is_platform_admin(auth.uid())) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  IF inv.status <> 'draft' THEN RAISE EXCEPTION 'Only draft invoices can be issued'; END IF;

  UPDATE academy.billing_invoices
     SET status = 'issued',
         issue_date = COALESCE(issue_date, CURRENT_DATE),
         issued_at = now(),
         balance = total - amount_paid
   WHERE id = _invoice_id;

  UPDATE academy.billing_charges
     SET status = 'invoiced'
   WHERE id IN (SELECT charge_id FROM academy.billing_invoice_lines
                WHERE invoice_id = _invoice_id AND charge_id IS NOT NULL);

  INSERT INTO academy.billing_audit_log(tenant_id, entity_type, entity_id, action, actor_id, after_state)
  VALUES (inv.tenant_id, 'invoice', _invoice_id, 'issued', auth.uid(),
          jsonb_build_object('total', inv.total));
  RETURN _invoice_id;
END; $$;


