  RETURN new_id;
END; $$;


--
-- Name: log_student_lifecycle_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.log_student_lifecycle_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'academy'
    AS $$
BEGIN
  IF TG_OP='UPDATE' AND NEW.lifecycle_status IS DISTINCT FROM OLD.lifecycle_status THEN
    INSERT INTO academy.student_status_history(tenant_id, student_id, previous_status, new_status, changed_by)
    VALUES (NEW.tenant_id, NEW.id, OLD.lifecycle_status, NEW.lifecycle_status, auth.uid());
  END IF;
  RETURN NEW;
END $$;


--
-- Name: log_student_status_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.log_student_status_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO academy.student_status_history(tenant_id, student_id, previous_status, new_status, changed_by)
    VALUES (NEW.tenant_id, NEW.id, NULL, COALESCE(NEW.status,'active'), auth.uid());
    RETURN NEW;
  END IF;
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    INSERT INTO academy.student_status_history(tenant_id, student_id, previous_status, new_status, reason, changed_by)
    VALUES (NEW.tenant_id, NEW.id, OLD.status, NEW.status, NEW.archive_reason, auth.uid());
  END IF;
  RETURN NEW;
END;
$$;


