--
-- Name: mirror_billing_payment_to_legacy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.mirror_billing_payment_to_legacy() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
  v_period text;
  v_note text;
  v_type text;
BEGIN
  IF coalesce(current_setting('academyos.skip_mirror', true), '') = 'on' THEN
    RETURN NEW;
  END IF;

  IF NEW.status IN ('succeeded', 'success') THEN
    v_period := substring(coalesce(NEW.remarks, '') from '\[period:([^\]]+)\]');
    IF v_period IS NULL OR v_period = '' THEN
      v_period := to_char(NEW.collected_at, 'YYYY-MM');
    END IF;

    v_note := nullif(btrim(regexp_replace(coalesce(NEW.remarks, ''), '\[period:[^\]]+\]', '')), '');

    v_type := CASE
      WHEN coalesce(NEW.remarks, '') ILIKE '%registration%' THEN 'registration'
      WHEN coalesce(NEW.remarks, '') ILIKE '%admission%' THEN 'admission'
      ELSE 'monthly'
    END;

    INSERT INTO academy.payments (
      tenant_id, student_id, amount, type, period, method, note, recorded_by,
      created_at, billing_payment_id
    )
    VALUES (
      NEW.tenant_id, NEW.student_id, NEW.amount, v_type, v_period,
      coalesce(nullif(NEW.method, ''), 'upi'), v_note,
      coalesce(NEW.collected_by, NEW.created_by),
      NEW.collected_at, NEW.id
    )
    ON CONFLICT (billing_payment_id) WHERE billing_payment_id IS NOT NULL DO UPDATE
      SET amount = EXCLUDED.amount,
          method = EXCLUDED.method,
          period = EXCLUDED.period,
          note = EXCLUDED.note;
  ELSE
    -- refunded / failed / pending -> keep the read model clean
    DELETE FROM academy.payments WHERE billing_payment_id = NEW.id;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: my_post_login_route(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.my_post_login_route() RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
  uid uuid := auth.uid();
BEGIN
  IF uid IS NULL THEN RETURN 'none'; END IF;

  IF EXISTS (SELECT 1 FROM academy.platform_admins WHERE user_id = uid) THEN
    RETURN 'platform_admin';
  END IF;

  IF EXISTS (
    SELECT 1 FROM academy.user_roles
     WHERE user_id = uid
       AND role IN ('owner','admin','coach','head_coach','assistant_coach','staff')
  ) THEN
    RETURN 'staff';
  END IF;

  IF EXISTS (SELECT 1 FROM academy.mc_parent_links WHERE parent_user_id = uid) THEN
    RETURN 'parent';
  END IF;

  IF EXISTS (SELECT 1 FROM academy.students WHERE user_id = uid) THEN
    RETURN 'student';
  END IF;

  IF EXISTS (SELECT 1 FROM academy.registrations WHERE applicant_user_id = uid) THEN
    RETURN 'student';
  END IF;

  RETURN 'none';
END;
$$;


--
-- Name: normalize_gender_db(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.normalize_gender_db(g text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
BEGIN
  IF g IS NULL THEN RETURN NULL; END IF;
  IF lower(trim(g)) IN ('female', 'girl') THEN RETURN 'female'; END IF;
  IF lower(trim(g)) IN ('male', 'boy') THEN RETURN 'male'; END IF;
  RETURN lower(trim(g));
END;
$$;


--
-- Name: owner_delete_member(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.owner_delete_member(_profile_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
  p_tenant uuid;
  p_user   uuid;
  p_role   text;
BEGIN
  SELECT tenant_id, user_id, role INTO p_tenant, p_user, p_role
    FROM academy.profiles WHERE id = _profile_id;
  IF p_tenant IS NULL THEN
    RAISE EXCEPTION 'Member not found';
  END IF;
  IF NOT (academy.is_tenant_owner(auth.uid(), p_tenant) OR academy.is_platform_admin(auth.uid())) THEN
    RAISE EXCEPTION 'Only the academy owner can remove a member';
  END IF;
  IF p_user = auth.uid() THEN
    RAISE EXCEPTION 'You cannot remove yourself';
  END IF;
  IF academy.is_platform_admin(p_user) THEN
    RAISE EXCEPTION 'Cannot remove a platform administrator';
  END IF;

  PERFORM academy.log_platform_action(
    p_tenant, 'member', _profile_id::text, 'delete',
    jsonb_build_object('user_id', p_user, 'role', p_role), NULL
  );

  DELETE FROM academy.profiles WHERE id = _profile_id;
END;
$$;


--
-- Name: owner_delete_student(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.owner_delete_student(_student_id uuid, _confirm_name text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
  s_tenant uuid;
  s_name   text;
BEGIN
  SELECT tenant_id, name INTO s_tenant, s_name FROM academy.students WHERE id = _student_id;
  IF s_tenant IS NULL THEN
    RAISE EXCEPTION 'Player not found';
  END IF;
  IF NOT (academy.is_tenant_owner(auth.uid(), s_tenant) OR academy.is_platform_admin(auth.uid())) THEN
    RAISE EXCEPTION 'Only the academy owner can remove a player';
  END IF;
  IF lower(trim(s_name)) <> lower(trim(_confirm_name)) THEN
    RAISE EXCEPTION 'Confirmation name does not match';
  END IF;

  -- Billing FKs are RESTRICT — clean up explicitly.
  DELETE FROM academy.billing_payment_allocations
    WHERE payment_id IN (SELECT id FROM academy.billing_payments WHERE student_id = _student_id);
  DELETE FROM academy.billing_payments        WHERE student_id = _student_id;
  DELETE FROM academy.billing_invoice_adjustments
    WHERE invoice_id IN (SELECT id FROM academy.billing_invoices WHERE student_id = _student_id);
  DELETE FROM academy.billing_invoice_lines
    WHERE invoice_id IN (SELECT id FROM academy.billing_invoices WHERE student_id = _student_id);
  DELETE FROM academy.billing_invoices        WHERE student_id = _student_id;
  DELETE FROM academy.billing_charges         WHERE student_id = _student_id;
  DELETE FROM academy.billing_subscriptions   WHERE student_id = _student_id;

  PERFORM academy.log_platform_action(
    s_tenant, 'student', _student_id::text, 'delete',
    jsonb_build_object('name', s_name), NULL
  );

  DELETE FROM academy.students WHERE id = _student_id;
END;
$$;


