--
-- Name: platform_delete_tenant(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.platform_delete_tenant(_tenant_id uuid, _confirm_name text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
  actual_name text;
BEGIN
  IF NOT academy.is_platform_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Only platform admins can remove a tenant';
  END IF;

  SELECT name INTO actual_name FROM academy.tenants WHERE id = _tenant_id;
  IF actual_name IS NULL THEN
    RAISE EXCEPTION 'Tenant not found';
  END IF;
  IF lower(trim(actual_name)) <> lower(trim(_confirm_name)) THEN
    RAISE EXCEPTION 'Confirmation name does not match';
  END IF;

  PERFORM academy.log_platform_action(
    _tenant_id, 'tenant', _tenant_id::text, 'delete',
    jsonb_build_object('name', actual_name), NULL
  );

  DELETE FROM academy.tenants WHERE id = _tenant_id;
END;
$$;


--
-- Name: process_daily_attendance_cleanup(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.process_daily_attendance_cleanup() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
BEGIN
    -- Auto check-out students who forgot to check out on any PREVIOUS day.
    -- We set check-out to the end of their respective session date.
    UPDATE academy.attendance_marks m
    SET 
        check_out_at = (s.session_date + INTERVAL '23 hours 59 minutes 59 seconds')::timestamptz,
        check_out_meta = COALESCE(m.check_out_meta, '{}'::jsonb) || jsonb_build_object('auto_checkout', true, 'exclude_from_hours', true),
        source = 'auto'
    FROM academy.attendance_sessions s
    WHERE m.session_id = s.id
        AND m.check_out_at IS NULL 
        AND m.status = 'present'
        AND s.session_date < CURRENT_DATE;
END;
$$;


--
-- Name: publish_notification(uuid, academy.notification_category, text, text, text, text, academy.notification_priority, jsonb, uuid, text, timestamp with time zone, academy.notification_channel[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.publish_notification(_recipient_user_id uuid, _category academy.notification_category, _type text, _title text, _body text DEFAULT NULL::text, _deep_link text DEFAULT NULL::text, _priority academy.notification_priority DEFAULT 'normal'::academy.notification_priority, _payload jsonb DEFAULT '{}'::jsonb, _tenant_id uuid DEFAULT NULL::uuid, _dedupe_key text DEFAULT NULL::text, _expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, _channels academy.notification_channel[] DEFAULT ARRAY['in_app'::academy.notification_channel]) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
  actor uuid := auth.uid();
  authorized boolean := false;
  existing_id uuid;
  new_id uuid;
  ch academy.notification_channel;
  pref_enabled boolean;
BEGIN
  IF _recipient_user_id IS NULL THEN RAISE EXCEPTION 'recipient required'; END IF;
  IF _title IS NULL OR btrim(_title) = '' THEN RAISE EXCEPTION 'title required'; END IF;

  -- Authorization: platform admin, self-send, or tenant member sending within
  -- the same tenant. service_role bypasses (auth.uid() is NULL).
  IF actor IS NULL THEN
    authorized := true;
  ELSIF academy.is_platform_admin(actor) THEN
    authorized := true;
  ELSIF actor = _recipient_user_id THEN
    authorized := true;
  ELSIF _tenant_id IS NOT NULL AND academy.is_tenant_member(actor, _tenant_id) THEN
    authorized := true;
  END IF;
  IF NOT authorized THEN RAISE EXCEPTION 'Not authorized to publish notification'; END IF;

  -- Dedupe
  IF _dedupe_key IS NOT NULL THEN
    SELECT id INTO existing_id FROM academy.notifications
      WHERE recipient_user_id = _recipient_user_id AND dedupe_key = _dedupe_key;
    IF existing_id IS NOT NULL THEN RETURN existing_id; END IF;
  END IF;

  INSERT INTO academy.notifications
    (recipient_user_id, tenant_id, category, type, title, body, deep_link,
     priority, payload, dedupe_key, expires_at, created_by)
  VALUES
    (_recipient_user_id, _tenant_id, _category, _type, _title, _body, _deep_link,
     _priority, COALESCE(_payload, '{}'::jsonb), _dedupe_key, _expires_at, actor)
  RETURNING id INTO new_id;

  -- Deliveries + outbox rows per requested channel, honoring preferences.
  FOREACH ch IN ARRAY COALESCE(_channels, ARRAY['in_app']::academy.notification_channel[]) LOOP
    SELECT enabled INTO pref_enabled FROM academy.notification_preferences
      WHERE user_id = _recipient_user_id AND category = _category AND channel = ch;
    IF pref_enabled IS FALSE THEN
      INSERT INTO academy.notification_deliveries(notification_id, channel, status)
      VALUES (new_id, ch, 'skipped');
      CONTINUE;
    END IF;

    IF ch = 'in_app' THEN
      INSERT INTO academy.notification_deliveries(notification_id, channel, status, delivered_at)
      VALUES (new_id, ch, 'delivered', now());
    ELSE
      INSERT INTO academy.notification_deliveries(notification_id, channel, status)
      VALUES (new_id, ch, 'queued');
      INSERT INTO academy.notification_outbox(notification_id, channel, payload)
      VALUES (new_id, ch, jsonb_build_object('title', _title, 'body', _body, 'deep_link', _deep_link));
    END IF;
  END LOOP;

  RETURN new_id;
END;
$$;


--
-- Name: publish_notification(uuid, academy.notification_category, text, text, text, text, academy.notification_priority, jsonb, uuid, text, timestamp with time zone, academy.notification_channel[], uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.publish_notification(_recipient_user_id uuid, _category academy.notification_category, _type text, _title text, _body text DEFAULT NULL::text, _deep_link text DEFAULT NULL::text, _priority academy.notification_priority DEFAULT 'normal'::academy.notification_priority, _payload jsonb DEFAULT '{}'::jsonb, _tenant_id uuid DEFAULT NULL::uuid, _dedupe_key text DEFAULT NULL::text, _expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, _channels academy.notification_channel[] DEFAULT ARRAY['in_app'::academy.notification_channel], _campaign_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
  actor uuid := auth.uid();
  authorized boolean := false;
  existing_id uuid;
  new_id uuid;
  ch academy.notification_channel;
  pref_enabled boolean;
BEGIN
  IF _recipient_user_id IS NULL THEN RAISE EXCEPTION 'recipient required'; END IF;
  IF _title IS NULL OR btrim(_title) = '' THEN RAISE EXCEPTION 'title required'; END IF;

  IF actor IS NULL THEN authorized := true;
  ELSIF academy.is_platform_admin(actor) THEN authorized := true;
  ELSIF actor = _recipient_user_id THEN authorized := true;
  ELSIF _tenant_id IS NOT NULL AND academy.is_tenant_member(actor, _tenant_id) THEN authorized := true;
  END IF;
  IF NOT authorized THEN RAISE EXCEPTION 'Not authorized to publish notification'; END IF;

  IF _dedupe_key IS NOT NULL THEN
    SELECT id INTO existing_id FROM academy.notifications
      WHERE recipient_user_id = _recipient_user_id AND dedupe_key = _dedupe_key;
    IF existing_id IS NOT NULL THEN RETURN existing_id; END IF;
  END IF;

  INSERT INTO academy.notifications
    (recipient_user_id, tenant_id, category, type, title, body, deep_link,
     priority, payload, dedupe_key, expires_at, created_by, campaign_id)
  VALUES
    (_recipient_user_id, _tenant_id, _category, _type, _title, _body, _deep_link,
     _priority, COALESCE(_payload, '{}'::jsonb), _dedupe_key, _expires_at, actor, _campaign_id)
  RETURNING id INTO new_id;

  FOREACH ch IN ARRAY COALESCE(_channels, ARRAY['in_app']::academy.notification_channel[]) LOOP
    SELECT enabled INTO pref_enabled FROM academy.notification_preferences
      WHERE user_id = _recipient_user_id AND category = _category AND channel = ch;
    IF pref_enabled IS FALSE THEN
      INSERT INTO academy.notification_deliveries(notification_id, channel, status)
      VALUES (new_id, ch, 'skipped');
      CONTINUE;
    END IF;
    IF ch = 'in_app' THEN
      INSERT INTO academy.notification_deliveries(notification_id, channel, status, delivered_at)
      VALUES (new_id, ch, 'delivered', now());
    ELSE
      INSERT INTO academy.notification_deliveries(notification_id, channel, status)
      VALUES (new_id, ch, 'queued');
      INSERT INTO academy.notification_outbox(notification_id, channel, payload)
      VALUES (new_id, ch, jsonb_build_object('title', _title, 'body', _body, 'deep_link', _deep_link));
    END IF;
  END LOOP;

  RETURN new_id;
END;
$$;


--
-- Name: qr_attendance_scan(text, double precision, double precision, double precision, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.qr_attendance_scan(_token text, _lat double precision, _lng double precision, _accuracy double precision DEFAULT NULL::double precision, _local_date date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
  t            academy.tenants%ROWTYPE;
  s            academy.students%ROWTYPE;
  v_uid        uuid := auth.uid();
  v_email      text := lower(coalesce(auth.jwt() ->> 'email', ''));
  v_dist       double precision;
  v_slack      double precision;
  v_date       date := coalesce(_local_date, CURRENT_DATE);
  v_session    uuid;
  v_open       academy.attendance_marks%ROWTYPE;
  v_last       timestamptz;
  v_action     text;
  v_total      integer;
  v_meta       jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'result', 'not_signed_in');
  END IF;

  SELECT * INTO t
  FROM academy.tenants
  WHERE attendance_qr_token = _token
    AND attendance_qr_enabled = true;

  IF t.id IS NULL THEN
    INSERT INTO academy.attendance_qr_scans (user_id, lat, lng, accuracy_m, result)
    VALUES (v_uid, _lat, _lng, _accuracy, 'invalid_token');
    RETURN jsonb_build_object('ok', false, 'result', 'invalid_token');
  END IF;

  SELECT * INTO s
  FROM academy.students
  WHERE tenant_id = t.id
    AND lifecycle_status = 'active'
    AND (user_id = v_uid OR (email IS NOT NULL AND v_email <> '' AND lower(email) = v_email))
  ORDER BY created_at
  LIMIT 1;

  IF s.id IS NULL THEN
    INSERT INTO academy.attendance_qr_scans (tenant_id, user_id, lat, lng, accuracy_m, result)
    VALUES (t.id, v_uid, _lat, _lng, _accuracy, 'not_student');
    RETURN jsonb_build_object('ok', false, 'result', 'not_student');
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(s.id::text, 0));

  IF v_date < CURRENT_DATE - 1 OR v_date > CURRENT_DATE + 1 THEN
    v_date := CURRENT_DATE;
  END IF;

  IF t.geo_lat IS NULL OR t.geo_lng IS NULL THEN
    INSERT INTO academy.attendance_qr_scans (tenant_id, student_id, user_id, lat, lng, accuracy_m, result)
    VALUES (t.id, s.id, v_uid, _lat, _lng, _accuracy, 'no_location_set');
    RETURN jsonb_build_object('ok', false, 'result', 'no_location_set');
  END IF;

  IF _lat IS NULL OR _lng IS NULL THEN
    INSERT INTO academy.attendance_qr_scans (tenant_id, student_id, user_id, accuracy_m, result)
    VALUES (t.id, s.id, v_uid, _accuracy, 'no_location');
    RETURN jsonb_build_object('ok', false, 'result', 'no_location');
  END IF;

  IF _lat < -90 OR _lat > 90 OR _lng < -180 OR _lng > 180 THEN
    INSERT INTO academy.attendance_qr_scans (tenant_id, student_id, user_id, lat, lng, accuracy_m, result)
    VALUES (t.id, s.id, v_uid, _lat, _lng, _accuracy, 'no_location');
    RETURN jsonb_build_object('ok', false, 'result', 'no_location');
  END IF;

  IF _accuracy IS NOT NULL AND _accuracy > 2000 THEN
    INSERT INTO academy.attendance_qr_scans (tenant_id, student_id, user_id, lat, lng, accuracy_m, result)
    VALUES (t.id, s.id, v_uid, _lat, _lng, _accuracy, 'low_accuracy');
    RETURN jsonb_build_object('ok', false, 'result', 'low_accuracy', 'accuracy_m', _accuracy);
  END IF;

  v_dist := academy.geo_distance_m(t.geo_lat, t.geo_lng, _lat, _lng);
  v_slack := least(coalesce(_accuracy, 0), 250);

  IF v_dist - v_slack > coalesce(t.geo_radius_m, 150) THEN
    INSERT INTO academy.attendance_qr_scans (tenant_id, student_id, user_id, lat, lng, accuracy_m, distance_m, result)
    VALUES (t.id, s.id, v_uid, _lat, _lng, _accuracy, v_dist, 'too_far');
    RETURN jsonb_build_object(
      'ok', false,
      'result', 'too_far',
      'distance_m', round(v_dist)::int,
      'radius_m', coalesce(t.geo_radius_m, 150)
    );
  END IF;

  SELECT max(created_at) INTO v_last
  FROM academy.attendance_qr_scans
  WHERE student_id = s.id AND result = 'ok';

  IF v_last IS NOT NULL
     AND v_last > now() - make_interval(secs => coalesce(t.attendance_qr_min_gap_seconds, 120)) THEN
    INSERT INTO academy.attendance_qr_scans (tenant_id, student_id, user_id, lat, lng, accuracy_m, distance_m, result)
    VALUES (t.id, s.id, v_uid, _lat, _lng, _accuracy, v_dist, 'rate_limited');
    RETURN jsonb_build_object(
      'ok', false,
      'result', 'rate_limited',
      'retry_after_seconds',
      greatest(1, ceil(extract(epoch FROM (
        v_last + make_interval(secs => coalesce(t.attendance_qr_min_gap_seconds, 120)) - now()
      )))::int)
    );
  END IF;

  PERFORM academy.auto_close_student_stale_attendance(s.id, v_date);

  v_meta := jsonb_build_object(
    'lat', _lat,
    'lng', _lng,
    'accuracy_m', _accuracy,
    'distance_m', round(v_dist)::int,
    'via', 'qr'
  );

  SELECT m.* INTO v_open
  FROM academy.attendance_marks m
  JOIN academy.attendance_sessions ses ON ses.id = m.session_id
  WHERE m.tenant_id = t.id
    AND m.student_id = s.id
    AND m.superseded_by IS NULL
    AND m.status = 'present'
    AND m.check_in_at IS NOT NULL
    AND m.check_out_at IS NULL
    AND ses.session_date = v_date
  ORDER BY m.check_in_at DESC
  LIMIT 1;

  IF v_open.id IS NOT NULL THEN
    UPDATE academy.attendance_marks
    SET check_out_at = now(), check_out_meta = v_meta
    WHERE id = v_open.id
      AND check_out_at IS NULL;
    v_action := 'check_out';
  ELSE
    IF s.batch_id IS NULL THEN
      INSERT INTO academy.attendance_qr_scans (tenant_id, student_id, user_id, lat, lng, accuracy_m, distance_m, result)
      VALUES (t.id, s.id, v_uid, _lat, _lng, _accuracy, v_dist, 'no_batch');
      RETURN jsonb_build_object('ok', false, 'result', 'no_batch');
    END IF;

    INSERT INTO academy.attendance_sessions (tenant_id, batch_id, session_date)
    VALUES (t.id, s.batch_id, v_date)
    ON CONFLICT (batch_id, session_date) DO NOTHING;

    SELECT id INTO v_session
    FROM academy.attendance_sessions
    WHERE tenant_id = t.id
      AND batch_id = s.batch_id
      AND session_date = v_date;

    IF v_session IS NULL THEN
      RAISE EXCEPTION 'attendance session unavailable';
    END IF;

    INSERT INTO academy.attendance_marks
        (tenant_id, session_id, student_id, status, check_in_at, source, marked_by, check_in_meta)
    VALUES
        (t.id, v_session, s.id, 'present', now(), 'qr', v_uid, v_meta);
        
    v_action := 'check_in';
  END IF;

  INSERT INTO academy.attendance_qr_scans
    (tenant_id, student_id, user_id, action, lat, lng, accuracy_m, distance_m, result)
  VALUES
    (t.id, s.id, v_uid, v_action, _lat, _lng, _accuracy, v_dist, 'ok');

  SELECT coalesce(sum(m.duration_minutes), 0)::int INTO v_total
  FROM academy.attendance_marks m
  JOIN academy.attendance_sessions ses ON ses.id = m.session_id
  WHERE m.student_id = s.id
    AND m.superseded_by IS NULL
    AND ses.session_date = v_date;

  RETURN jsonb_build_object(
    'ok', true,
    'result', 'ok',
    'action', v_action,
    'student_name', s.name,
    'academy_name', t.name,
    'at', now(),
    'distance_m', round(v_dist)::int,
    'total_minutes_today', v_total
  );
END;
$$;


--
-- Name: record_billing_payment(uuid, uuid, numeric, text, jsonb, text, text, text, text, timestamp with time zone, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.record_billing_payment(_tenant_id uuid, _student_id uuid, _amount numeric, _method text, _allocations jsonb, _reference_number text DEFAULT NULL::text, _gateway text DEFAULT NULL::text, _gateway_reference text DEFAULT NULL::text, _idempotency_key text DEFAULT NULL::text, _collected_at timestamp with time zone DEFAULT now(), _remarks text DEFAULT NULL::text, _status text DEFAULT 'succeeded'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
  existing_id uuid;
  new_payment_id uuid;
  alloc_sum numeric := 0;
  alloc jsonb;
  inv academy.billing_invoices%ROWTYPE;
  new_paid numeric;
  new_status text;
BEGIN
  IF NOT (academy.is_tenant_owner(auth.uid(), _tenant_id) OR academy.is_platform_admin(auth.uid())) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  IF _amount <= 0 THEN RAISE EXCEPTION 'Amount must be positive'; END IF;

  -- Idempotency
  IF _idempotency_key IS NOT NULL THEN
    SELECT id INTO existing_id FROM academy.billing_payments
     WHERE tenant_id = _tenant_id AND idempotency_key = _idempotency_key;
    IF existing_id IS NOT NULL THEN RETURN existing_id; END IF;
  END IF;

  -- Validate allocations
  IF _allocations IS NOT NULL THEN
    FOR alloc IN SELECT * FROM jsonb_array_elements(_allocations) LOOP
      alloc_sum := alloc_sum + (alloc->>'amount')::numeric;
    END LOOP;
    IF alloc_sum > _amount + 0.005 THEN
      RAISE EXCEPTION 'Allocations (%) exceed payment amount (%)', alloc_sum, _amount;
    END IF;
  END IF;

  INSERT INTO academy.billing_payments
    (tenant_id, student_id, amount, method, reference_number,
     gateway, gateway_reference, idempotency_key, status,
     collected_by, collected_at, remarks, created_by)
  VALUES
    (_tenant_id, _student_id, _amount, _method, _reference_number,
     _gateway, _gateway_reference, _idempotency_key, _status,
     auth.uid(), _collected_at, _remarks, auth.uid())
  RETURNING id INTO new_payment_id;

  -- Only allocate if payment is succeeded
  IF _status = 'succeeded' AND _allocations IS NOT NULL THEN
    FOR alloc IN SELECT * FROM jsonb_array_elements(_allocations) LOOP
      INSERT INTO academy.billing_payment_allocations
        (tenant_id, payment_id, invoice_id, amount, created_by)
      VALUES
        (_tenant_id, new_payment_id, (alloc->>'invoice_id')::uuid,
         (alloc->>'amount')::numeric, auth.uid());

      SELECT * INTO inv FROM academy.billing_invoices
        WHERE id = (alloc->>'invoice_id')::uuid AND tenant_id = _tenant_id
        FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION 'Invoice not in tenant'; END IF;
      IF inv.status = 'void' THEN RAISE EXCEPTION 'Cannot allocate to void invoice'; END IF;

      new_paid := inv.amount_paid + (alloc->>'amount')::numeric;
      IF new_paid >= inv.total THEN new_status := 'paid';
      ELSIF new_paid > 0 THEN new_status := 'partially_paid';
      ELSE new_status := inv.status; END IF;

      UPDATE academy.billing_invoices
         SET amount_paid = new_paid,
             balance = GREATEST(total - new_paid, 0),
             status = new_status
       WHERE id = inv.id;
    END LOOP;
  END IF;

  INSERT INTO academy.billing_audit_log(tenant_id, entity_type, entity_id, action, actor_id, after_state)
  VALUES (_tenant_id, 'payment', new_payment_id, 'created', auth.uid(),
          jsonb_build_object('amount', _amount, 'method', _method, 'allocated', alloc_sum));

  RETURN new_payment_id;
END; $$;


--
-- Name: release_match_scoring_lock(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.release_match_scoring_lock(_match_id uuid, _session_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
BEGIN
  DELETE FROM academy.mc_scoring_locks
    WHERE match_id = _match_id
      AND owner_user_id = auth.uid()
      AND session_id = _session_id;
  RETURN FOUND;
END; $$;


--
-- Name: render_template_preview(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.render_template_preview(_title text, _body text, _vars jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'academy'
    AS $$
DECLARE
  k text; v text; rendered_title text := COALESCE(_title,''); rendered_body text := COALESCE(_body,'');
BEGIN
  IF _vars IS NULL THEN
    RETURN jsonb_build_object('title', rendered_title, 'body', rendered_body);
  END IF;
  FOR k, v IN SELECT key, value FROM jsonb_each_text(_vars) LOOP
    rendered_title := replace(rendered_title, '{{' || k || '}}', COALESCE(v,''));
    rendered_body := replace(rendered_body, '{{' || k || '}}', COALESCE(v,''));
  END LOOP;
  RETURN jsonb_build_object('title', rendered_title, 'body', rendered_body);
END; $$;


--
-- Name: resolve_student_monthly_fee(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.resolve_student_monthly_fee(p_fee_plan_id uuid, p_gender text, p_tenant_id uuid) RETURNS numeric
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_amount numeric;
  v_female_amount numeric;
  v_gender_pricing_enabled boolean;
BEGIN
  -- Check if gender pricing is enabled for the tenant
  SELECT gender_pricing_enabled INTO v_gender_pricing_enabled 
  FROM academy.tenants WHERE id = p_tenant_id;

  SELECT amount, female_amount INTO v_amount, v_female_amount
  FROM academy.fee_plans WHERE id = p_fee_plan_id;

  IF v_gender_pricing_enabled AND academy.normalize_gender_db(p_gender) = 'female' AND v_female_amount IS NOT NULL THEN
    RETURN v_female_amount;
  END IF;

  RETURN COALESCE(v_amount, 0);
END;
$$;


--
-- Name: resubmit_registration(uuid, text, text, uuid, uuid, date, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.resubmit_registration(_registration_id uuid, _name text, _phone text, _fee_plan_id uuid DEFAULT NULL::uuid, _batch_id uuid DEFAULT NULL::uuid, _dob date DEFAULT NULL::date, _guardian_name text DEFAULT NULL::text, _address text DEFAULT NULL::text, _gender text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
  v_tenant_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Strict ownership: caller must be the exact applicant_user_id on the row. No NULL bypass.
  SELECT tenant_id INTO v_tenant_id
  FROM academy.registrations
  WHERE id = _registration_id
    AND applicant_user_id = auth.uid()
    AND review_status = 'changes_requested';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Registration not found or not in editable state.';
  END IF;

  IF _fee_plan_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM academy.fee_plans WHERE id = _fee_plan_id AND tenant_id = v_tenant_id AND active = true
  ) THEN
    RAISE EXCEPTION 'Invalid fee plan';
  END IF;

  IF _batch_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM academy.batches WHERE id = _batch_id AND tenant_id = v_tenant_id AND active = true
  ) THEN
    RAISE EXCEPTION 'Invalid batch';
  END IF;

  UPDATE academy.registrations
  SET
    name = _name,
    phone = _phone,
    fee_plan_id = _fee_plan_id,
    batch_id = _batch_id,
    dob = _dob,
    guardian_name = _guardian_name,
    address = _address,
    gender = _gender,
    review_status = 'pending',
    review_notes = NULL,
    updated_at = now()
  WHERE id = _registration_id;
END;
$$;




--
-- Name: schedule_campaign(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.schedule_campaign(_campaign_id uuid, _when timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE c academy.comm_campaigns%ROWTYPE;
BEGIN
  SELECT * INTO c FROM academy.comm_campaigns WHERE id = _campaign_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Campaign not found'; END IF;
  IF NOT (academy.is_tenant_member(auth.uid(), c.tenant_id) OR academy.is_platform_admin(auth.uid())) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  IF c.status NOT IN ('draft','scheduled') THEN
    RAISE EXCEPTION 'Only draft/scheduled campaigns can be (re)scheduled';
  END IF;
  UPDATE academy.comm_campaigns
     SET status = 'scheduled', scheduled_for = _when, last_error = NULL
   WHERE id = _campaign_id;
END; $$;


--
-- Name: send_campaign(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.send_campaign(_campaign_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
  c academy.comm_campaigns%ROWTYPE;
  aud jsonb;
  aud_kind text;
  batch_ids uuid[];
  student_ids uuid[];
  parent_ids uuid[];
  admin_ids uuid[];
  include_students boolean;
  include_parents boolean;
  include_admins boolean;
  rec_uid uuid;
  rec_name text;
  rec_student_id uuid;
  rendered_title text;
  rendered_body text;
  notif_id uuid;
  total int := 0; delivered int := 0; failed int := 0;
  var_map jsonb;
  academy_name text;
BEGIN
  SELECT * INTO c FROM academy.comm_campaigns WHERE id = _campaign_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Campaign not found'; END IF;
  IF NOT (academy.is_tenant_member(auth.uid(), c.tenant_id) OR academy.is_platform_admin(auth.uid())) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  IF c.category = 'billing' AND NOT (academy.is_tenant_owner(auth.uid(), c.tenant_id) OR academy.is_platform_admin(auth.uid())) THEN
    RAISE EXCEPTION 'Only owners can send billing campaigns';
  END IF;
  IF c.status NOT IN ('draft','scheduled','failed') THEN
    RAISE EXCEPTION 'Campaign already % — cannot send', c.status;
  END IF;

  UPDATE academy.comm_campaigns SET status = 'sending', last_error = NULL WHERE id = _campaign_id;

  SELECT name INTO academy_name FROM academy.tenants WHERE id = c.tenant_id;
  aud := COALESCE(c.audience, '{}'::jsonb);
  aud_kind := COALESCE(aud->>'kind', 'all');
  batch_ids := COALESCE((SELECT array_agg((v)::uuid) FROM jsonb_array_elements_text(COALESCE(aud->'batch_ids','[]'::jsonb)) v), '{}'::uuid[]);
  student_ids := COALESCE((SELECT array_agg((v)::uuid) FROM jsonb_array_elements_text(COALESCE(aud->'student_ids','[]'::jsonb)) v), '{}'::uuid[]);
  parent_ids := COALESCE((SELECT array_agg((v)::uuid) FROM jsonb_array_elements_text(COALESCE(aud->'parent_ids','[]'::jsonb)) v), '{}'::uuid[]);
  admin_ids := COALESCE((SELECT array_agg((v)::uuid) FROM jsonb_array_elements_text(COALESCE(aud->'admin_ids','[]'::jsonb)) v), '{}'::uuid[]);
  include_students := COALESCE((aud->>'include_students')::boolean, aud_kind IN ('all','students'));
  include_parents  := COALESCE((aud->>'include_parents')::boolean,  aud_kind IN ('all','parents'));
  include_admins   := COALESCE((aud->>'include_admins')::boolean,   aud_kind IN ('all','admins'));

  -- Resolve into a temp set of (user_id, student_id, name)
  CREATE TEMP TABLE _campaign_targets (
    user_id uuid PRIMARY KEY,
    student_id uuid,
    name text
  ) ON COMMIT DROP;

  -- Students in tenant (optionally batch/id filtered)
  IF include_students OR aud_kind = 'students' OR array_length(student_ids,1) IS NOT NULL THEN
    INSERT INTO _campaign_targets(user_id, student_id, name)
    SELECT DISTINCT s.user_id, s.id, s.name
      FROM academy.students s
     WHERE s.tenant_id = c.tenant_id
       AND s.user_id IS NOT NULL
       AND s.archived_at IS NULL
       AND (array_length(batch_ids,1) IS NULL OR s.batch_id = ANY(batch_ids))
       AND (array_length(student_ids,1) IS NULL OR s.id = ANY(student_ids))
    ON CONFLICT (user_id) DO NOTHING;
  END IF;

  -- Parents linked to tenant students
  IF include_parents OR aud_kind = 'parents' OR array_length(parent_ids,1) IS NOT NULL THEN
    INSERT INTO _campaign_targets(user_id, student_id, name)
    SELECT DISTINCT l.parent_user_id, l.student_id, s.name
      FROM academy.mc_parent_links l
      JOIN academy.students s ON s.id = l.student_id
     WHERE s.tenant_id = c.tenant_id
       AND (array_length(batch_ids,1) IS NULL OR s.batch_id = ANY(batch_ids))
       AND (array_length(student_ids,1) IS NULL OR s.id = ANY(student_ids))
       AND (array_length(parent_ids,1) IS NULL OR l.parent_user_id = ANY(parent_ids))
    ON CONFLICT (user_id) DO NOTHING;
  END IF;

  -- Tenant staff (owners + admins)
  IF include_admins OR aud_kind = 'admins' OR array_length(admin_ids,1) IS NOT NULL THEN
    INSERT INTO _campaign_targets(user_id, student_id, name)
    SELECT DISTINCT p.user_id, NULL, NULL
      FROM academy.profiles p
     WHERE p.tenant_id = c.tenant_id
       AND p.role IN ('owner','admin','coach','staff')
       AND (array_length(admin_ids,1) IS NULL OR p.user_id = ANY(admin_ids))
    ON CONFLICT (user_id) DO NOTHING;
  END IF;

  -- Fan out
  FOR rec_uid, rec_student_id, rec_name IN SELECT user_id, student_id, name FROM _campaign_targets LOOP
    total := total + 1;
    BEGIN
      var_map := jsonb_build_object(
        'student_name', COALESCE(rec_name, ''),
        'academy', COALESCE(academy_name, ''),
        'date', to_char(now(), 'DD Mon YYYY')
      );
      rendered_title := c.title;
      rendered_body := COALESCE(c.body, '');
      SELECT (r->>'title'), (r->>'body') INTO rendered_title, rendered_body
        FROM academy.render_template_preview(c.title, c.body, var_map) r;

      notif_id := academy.publish_notification(
        _recipient_user_id := rec_uid,
        _category := c.category,
        _type := c.message_type,
        _title := rendered_title,
        _body := rendered_body,
        _deep_link := c.deep_link,
        _priority := c.priority,
        _payload := jsonb_build_object('campaign_id', c.id, 'student_id', rec_student_id),
        _tenant_id := c.tenant_id,
        _dedupe_key := NULL,
        _expires_at := NULL,
        _channels := c.channels,
        _campaign_id := c.id
      );
      INSERT INTO academy.comm_campaign_recipients(tenant_id, campaign_id, recipient_user_id, notification_id)
      VALUES (c.tenant_id, c.id, rec_uid, notif_id)
      ON CONFLICT DO NOTHING;
      delivered := delivered + 1;
    EXCEPTION WHEN OTHERS THEN
      failed := failed + 1;
    END;
  END LOOP;

  UPDATE academy.comm_campaigns
     SET status = CASE WHEN failed > 0 AND delivered = 0 THEN 'failed' ELSE 'sent' END,
         sent_at = now(),
         recipient_count = total,
         delivered_count = delivered,
         failed_count = failed
   WHERE id = _campaign_id;

  RETURN jsonb_build_object('total', total, 'delivered', delivered, 'failed', failed);
END; $$;


--
-- Name: set_attendance_qr_settings(uuid, boolean, double precision, double precision, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.set_attendance_qr_settings(_tenant_id uuid, _enabled boolean DEFAULT NULL::boolean, _lat double precision DEFAULT NULL::double precision, _lng double precision DEFAULT NULL::double precision, _radius_m integer DEFAULT NULL::integer, _rotate_token boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
  t academy.tenants%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not signed in';
  END IF;

  IF NOT (
    academy.is_tenant_owner(auth.uid(), _tenant_id)
    OR academy.has_role(auth.uid(), _tenant_id, 'admin'::academy.app_role)
  ) THEN
    RAISE EXCEPTION 'not authorised';
  END IF;

  UPDATE academy.tenants
  SET
    attendance_qr_enabled = coalesce(_enabled, attendance_qr_enabled, false),
    geo_lat = coalesce(_lat, geo_lat),
    geo_lng = coalesce(_lng, geo_lng),
    geo_radius_m = coalesce(greatest(least(_radius_m, 1000), 50), geo_radius_m, 150),
    attendance_qr_token = CASE
      WHEN _rotate_token OR attendance_qr_token IS NULL
        THEN encode(extensions.gen_random_bytes(16), 'hex')
      ELSE attendance_qr_token
    END
  WHERE id = _tenant_id
  RETURNING * INTO t;

  IF t.id IS NULL THEN
    RAISE EXCEPTION 'academy not found';
  END IF;

  RETURN jsonb_build_object(
    'enabled', coalesce(t.attendance_qr_enabled, false),
    'token', t.attendance_qr_token,
    'lat', t.geo_lat,
    'lng', t.geo_lng,
    'radius_m', coalesce(t.geo_radius_m, 150),
    'min_gap_seconds', coalesce(t.attendance_qr_min_gap_seconds, 120)
  );
END;
$$;


--
-- Name: set_my_username(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.set_my_username(_username text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $_$
DECLARE
  uid uuid := auth.uid();
  uname text := lower(trim(_username));
BEGIN
  IF uid IS NULL THEN
    RAISE EXCEPTION 'Not signed in';
  END IF;
  IF uname !~ '^[a-z0-9._]{3,20}$' THEN
    RAISE EXCEPTION 'Username must be 3-20 characters: letters, numbers, dot or underscore';
  END IF;
  IF EXISTS (SELECT 1 FROM academy.user_usernames u WHERE lower(u.username) = uname AND u.user_id <> uid) THEN
    RAISE EXCEPTION 'That username is already taken';
  END IF;

  INSERT INTO academy.user_usernames (user_id, username)
  VALUES (uid, uname)
  ON CONFLICT (user_id) DO UPDATE SET username = EXCLUDED.username, updated_at = now();

  RETURN uname;
END;
$_$;


--
-- Name: set_remark_defaults(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.set_remark_defaults() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
  v_role text;
BEGIN
  -- Only apply on INSERT paths; leave UPDATE alone
  IF TG_OP <> 'INSERT' THEN
    RETURN NEW;
  END IF;

  -- Pick the highest-privilege role this user has in this tenant
  SELECT role::text INTO v_role
  FROM academy.user_roles
  WHERE user_id = COALESCE(NEW.author_user_id, auth.uid())
    AND tenant_id = NEW.tenant_id
  ORDER BY CASE role::text
    WHEN 'owner' THEN 1
    WHEN 'admin' THEN 2
    WHEN 'head_coach' THEN 3
    WHEN 'coach' THEN 4
    WHEN 'assistant_coach' THEN 5
    ELSE 9
  END
  LIMIT 1;

  -- Fill submitted_by_role if the client did not (or set it wrong)
  NEW.submitted_by_role := v_role;

  -- Coaches & assistant coaches → pending; anyone else → keep default (approved)
  IF v_role IN ('coach', 'assistant_coach') THEN
    NEW.approval_status := 'pending';
    NEW.approved_by := NULL;
    NEW.approved_at := NULL;
  ELSIF v_role IN ('head_coach', 'admin', 'owner') THEN
    -- Auto-approve; stamp approver
    NEW.approval_status := 'approved';
    NEW.approved_by := COALESCE(NEW.approved_by, auth.uid());
    NEW.approved_at := COALESCE(NEW.approved_at, now());
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: set_tenant_feature(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.set_tenant_feature(_tenant_id uuid, _key text, _enabled boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE before_features jsonb; after_features jsonb;
BEGIN
  IF NOT academy.is_platform_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  SELECT features INTO before_features FROM academy.tenants WHERE id = _tenant_id;
  IF before_features IS NULL THEN before_features := '{}'::jsonb; END IF;
  after_features := before_features || jsonb_build_object(_key, _enabled);
  UPDATE academy.tenants SET features = after_features WHERE id = _tenant_id;
  INSERT INTO academy.platform_audit_log(actor_id, tenant_id, target_type, target_id, action, before_state, after_state)
  VALUES (auth.uid(), _tenant_id, 'flag', _key, 'flag_toggle',
          jsonb_build_object(_key, before_features->_key),
          jsonb_build_object(_key, _enabled));
END; $$;


