--
-- Name: slugify(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.slugify(_input text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'academy'
    AS $$
  SELECT trim(BOTH '-' FROM
    regexp_replace(
      regexp_replace(lower(coalesce(_input, '')), '[^a-z0-9]+', '-', 'g'),
      '-+', '-', 'g'
    )
  );
$$;


--
-- Name: staff_scan_student_card(text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.staff_scan_student_card(_card_token text, _local_date date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
  t         academy.tenants%ROWTYPE;
  s         academy.students%ROWTYPE;
  v_uid     uuid := auth.uid();
  v_date    date := coalesce(_local_date, CURRENT_DATE);
  v_session uuid;
  v_open    academy.attendance_marks%ROWTYPE;
  v_last    timestamptz;
  v_action  text;
  v_total   int;
  v_meta    jsonb;
  v_allowed boolean;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'result', 'not_signed_in');
  END IF;

  SELECT * INTO s FROM academy.students WHERE card_token = _card_token;
  IF s.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'result', 'invalid_card');
  END IF;

  SELECT * INTO t FROM academy.tenants WHERE id = s.tenant_id;
  IF t.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'result', 'invalid_card');
  END IF;

  v_allowed := (t.owner_id = v_uid)
    OR academy.has_role(v_uid, t.id, 'owner')
    OR academy.has_role(v_uid, t.id, 'admin')
    OR academy.has_role(v_uid, t.id, 'head_coach')
    OR academy.has_role(v_uid, t.id, 'coach')
    OR academy.has_role(v_uid, t.id, 'assistant_coach')
    OR (s.batch_id IS NOT NULL AND academy.is_coach_for_batch(s.batch_id));

  IF NOT v_allowed THEN
    RETURN jsonb_build_object('ok', false, 'result', 'not_staff');
  END IF;

  IF s.lifecycle_status = 'left' OR s.status = 'left' THEN
    RETURN jsonb_build_object('ok', false, 'result', 'inactive_student');
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(s.id::text, 0));

  IF v_date < CURRENT_DATE - 1 OR v_date > CURRENT_DATE + 1 THEN
    v_date := CURRENT_DATE;
  END IF;

  SELECT max(created_at) INTO v_last
  FROM academy.attendance_qr_scans
  WHERE student_id = s.id AND result = 'ok';

  IF v_last IS NOT NULL
     AND v_last > now() - make_interval(secs => coalesce(t.attendance_qr_min_gap_seconds, 120)) THEN
    INSERT INTO academy.attendance_qr_scans (tenant_id, student_id, user_id, result)
    VALUES (t.id, s.id, v_uid, 'rate_limited');
    RETURN jsonb_build_object(
      'ok', false,
      'result', 'rate_limited',
      'student_name', s.name,
      'retry_after_seconds',
      greatest(1, ceil(extract(epoch FROM (
        v_last + make_interval(secs => coalesce(t.attendance_qr_min_gap_seconds, 120)) - now()
      )))::int)
    );
  END IF;

  PERFORM academy.auto_close_student_stale_attendance(s.id, v_date);

  v_meta := jsonb_build_object('via', 'id_card', 'scanned_by', v_uid);

  SELECT m.* INTO v_open
  FROM academy.attendance_marks m
  JOIN academy.attendance_sessions ses ON ses.id = m.session_id
  WHERE m.tenant_id = t.id
    AND m.student_id = s.id
    AND m.superseded_by IS NULL
    AND m.status = 'present'
    AND m.check_in_at IS NOT NULL
    AND m.check_out_at IS NULL
    AND ses.session_date = v_date
  ORDER BY m.check_in_at DESC
  LIMIT 1;

  IF v_open.id IS NOT NULL THEN
    UPDATE academy.attendance_marks
    SET check_out_at = now(), check_out_meta = v_meta
    WHERE id = v_open.id AND check_out_at IS NULL;
    v_action := 'check_out';
  ELSE
    IF s.batch_id IS NULL THEN
      INSERT INTO academy.attendance_qr_scans (tenant_id, student_id, user_id, result)
      VALUES (t.id, s.id, v_uid, 'no_batch');
      RETURN jsonb_build_object('ok', false, 'result', 'no_batch', 'student_name', s.name);
    END IF;

    INSERT INTO academy.attendance_sessions (tenant_id, batch_id, session_date)
    VALUES (t.id, s.batch_id, v_date)
    ON CONFLICT (batch_id, session_date) DO NOTHING;

    SELECT id INTO v_session
    FROM academy.attendance_sessions
    WHERE tenant_id = t.id AND batch_id = s.batch_id AND session_date = v_date;

    IF v_session IS NULL THEN
      RAISE EXCEPTION 'attendance session unavailable';
    END IF;

    INSERT INTO academy.attendance_marks
        (tenant_id, session_id, student_id, status, check_in_at, source, marked_by, check_in_meta)
    VALUES
        (t.id, v_session, s.id, 'present', now(), 'qr', v_uid, v_meta);

    v_action := 'check_in';
  END IF;

  INSERT INTO academy.attendance_qr_scans (tenant_id, student_id, user_id, action, result)
  VALUES (t.id, s.id, v_uid, v_action, 'ok');

  SELECT coalesce(sum(m.duration_minutes), 0)::int INTO v_total
  FROM academy.attendance_marks m
  JOIN academy.attendance_sessions ses ON ses.id = m.session_id
  WHERE m.student_id = s.id
    AND m.superseded_by IS NULL
    AND ses.session_date = v_date;

  RETURN jsonb_build_object(
    'ok', true,
    'result', 'ok',
    'action', v_action,
    'student_name', s.name,
    'player_id', s.player_id,
    'academy_name', t.name,
    'at', now(),
    'total_minutes_today', v_total
  );
END;
$$;


--
-- Name: staff_scan_student_card(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.staff_scan_student_card(_card_token uuid, _local_date date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
  t         academy.tenants%ROWTYPE;
  s         academy.students%ROWTYPE;
  v_uid     uuid := auth.uid();
  v_date    date := coalesce(_local_date, CURRENT_DATE);
  v_session uuid;
  v_open    academy.attendance_marks%ROWTYPE;
  v_last    timestamptz;
  v_action  text;
  v_total   int;
  v_meta    jsonb;
  v_allowed boolean;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'result', 'not_signed_in');
  END IF;

  SELECT * INTO s FROM academy.students WHERE card_token = _card_token;
  IF s.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'result', 'invalid_card');
  END IF;

  SELECT * INTO t FROM academy.tenants WHERE id = s.tenant_id;
  IF t.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'result', 'invalid_card');
  END IF;

  v_allowed := (t.owner_id = v_uid)
    OR academy.has_role(v_uid, t.id, 'owner')
    OR academy.has_role(v_uid, t.id, 'admin')
    OR academy.has_role(v_uid, t.id, 'head_coach')
    OR academy.has_role(v_uid, t.id, 'coach')
    OR academy.has_role(v_uid, t.id, 'assistant_coach')
    OR (s.batch_id IS NOT NULL AND academy.is_coach_for_batch(s.batch_id));

  IF NOT v_allowed THEN
    RETURN jsonb_build_object('ok', false, 'result', 'not_staff');
  END IF;

  IF s.lifecycle_status = 'left' OR s.status = 'left' THEN
    RETURN jsonb_build_object('ok', false, 'result', 'inactive_student');
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(s.id::text, 0));

  IF v_date < CURRENT_DATE - 1 OR v_date > CURRENT_DATE + 1 THEN
    v_date := CURRENT_DATE;
  END IF;

  SELECT max(created_at) INTO v_last
  FROM academy.attendance_qr_scans
  WHERE student_id = s.id AND result = 'ok';

  IF v_last IS NOT NULL
     AND v_last > now() - make_interval(secs => coalesce(t.attendance_qr_min_gap_seconds, 120)) THEN
    INSERT INTO academy.attendance_qr_scans (tenant_id, student_id, user_id, result)
    VALUES (t.id, s.id, v_uid, 'rate_limited');
    RETURN jsonb_build_object(
      'ok', false,
      'result', 'rate_limited',
      'student_name', s.name,
      'retry_after_seconds',
      greatest(1, ceil(extract(epoch FROM (
        v_last + make_interval(secs => coalesce(t.attendance_qr_min_gap_seconds, 120)) - now()
      )))::int)
    );
  END IF;

  PERFORM academy.auto_close_student_stale_attendance(s.id, v_date);

  v_meta := jsonb_build_object('via', 'id_card', 'scanned_by', v_uid);

  SELECT m.* INTO v_open
  FROM academy.attendance_marks m
  JOIN academy.attendance_sessions ses ON ses.id = m.session_id
  WHERE m.tenant_id = t.id
    AND m.student_id = s.id
    AND m.superseded_by IS NULL
    AND m.status = 'present'
    AND m.check_in_at IS NOT NULL
    AND m.check_out_at IS NULL
    AND ses.session_date = v_date
  ORDER BY m.check_in_at DESC
  LIMIT 1;

  IF v_open.id IS NOT NULL THEN
    UPDATE academy.attendance_marks
    SET check_out_at = now(), check_out_meta = v_meta
    WHERE id = v_open.id AND check_out_at IS NULL;
    v_action := 'check_out';
  ELSE
    IF s.batch_id IS NULL THEN
      INSERT INTO academy.attendance_qr_scans (tenant_id, student_id, user_id, result)
      VALUES (t.id, s.id, v_uid, 'no_batch');
      RETURN jsonb_build_object('ok', false, 'result', 'no_batch', 'student_name', s.name);
    END IF;

    INSERT INTO academy.attendance_sessions (tenant_id, batch_id, session_date)
    VALUES (t.id, s.batch_id, v_date)
    ON CONFLICT (batch_id, session_date) DO NOTHING;

    SELECT id INTO v_session
    FROM academy.attendance_sessions
    WHERE tenant_id = t.id AND batch_id = s.batch_id AND session_date = v_date;

    IF v_session IS NULL THEN
      RAISE EXCEPTION 'attendance session unavailable';
    END IF;

    BEGIN
      INSERT INTO academy.attendance_marks
        (tenant_id, session_id, student_id, status, check_in_at, source, marked_by, check_in_meta)
      VALUES
        (t.id, v_session, s.id, 'present', now(), 'qr', v_uid, v_meta);
    EXCEPTION WHEN unique_violation THEN
      NULL;
    END;
    v_action := 'check_in';
  END IF;

  INSERT INTO academy.attendance_qr_scans (tenant_id, student_id, user_id, action, result)
  VALUES (t.id, s.id, v_uid, v_action, 'ok');

  SELECT coalesce(sum(m.duration_minutes), 0)::int INTO v_total
  FROM academy.attendance_marks m
  JOIN academy.attendance_sessions ses ON ses.id = m.session_id
  WHERE m.student_id = s.id
    AND m.superseded_by IS NULL
    AND ses.session_date = v_date;

  RETURN jsonb_build_object(
    'ok', true,
    'result', 'ok',
    'action', v_action,
    'student_name', s.name,
    'player_id', s.player_id,
    'academy_name', t.name,
    'at', now(),
    'total_minutes_today', v_total
  );
END;
$$;


--
-- Name: student_can_read_session(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.student_can_read_session(_session_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM academy.attendance_marks m
    WHERE m.session_id = _session_id
      AND academy.is_my_student(m.student_id)
  );
$$;


--
-- Name: submit_lead(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.submit_lead(_tenant_id uuid, _name text, _phone text, _message text DEFAULT NULL::text, _source text DEFAULT 'site'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE new_id uuid;
BEGIN
  IF _name IS NULL OR btrim(_name) = '' THEN RAISE EXCEPTION 'Name is required'; END IF;
  IF _phone IS NULL OR btrim(_phone) = '' THEN RAISE EXCEPTION 'Phone is required'; END IF;
  IF NOT EXISTS (SELECT 1 FROM academy.tenants WHERE id = _tenant_id AND status = 'active') THEN
    RAISE EXCEPTION 'Academy not accepting enquiries';
  END IF;

  -- 10 enquiries per phone per academy per 10 minutes.
  IF NOT academy.check_rate_limit(
       'lead:' || _tenant_id::text || ':' || regexp_replace(btrim(_phone), '\D', '', 'g'),
       10, 600) THEN
    RAISE EXCEPTION 'Too many enquiries submitted. Please try again in a few minutes.';
  END IF;

  INSERT INTO academy.leads (tenant_id, name, phone, message, source)
  VALUES (_tenant_id, btrim(_name), btrim(_phone), NULLIF(btrim(_message),''),
          COALESCE(NULLIF(btrim(_source),''),'site'))
  RETURNING id INTO new_id;
  RETURN new_id;
END; $$;


--
-- Name: submit_registration(uuid, text, text, uuid, uuid, date, text, text, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.submit_registration(_tenant_id uuid, _name text, _phone text, _fee_plan_id uuid, _batch_id uuid DEFAULT NULL::uuid, _dob date DEFAULT NULL::date, _guardian_name text DEFAULT NULL::text, _guardian_phone text DEFAULT NULL::text, _whatsapp text DEFAULT NULL::text, _policy_acceptances jsonb DEFAULT '[]'::jsonb, _lead_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE new_id uuid;
BEGIN
  IF _name IS NULL OR btrim(_name) = '' THEN RAISE EXCEPTION 'Name is required'; END IF;
  IF _phone IS NULL OR btrim(_phone) = '' THEN RAISE EXCEPTION 'Phone is required'; END IF;
  IF _fee_plan_id IS NULL THEN RAISE EXCEPTION 'Fee plan is required'; END IF;

  IF NOT EXISTS (SELECT 1 FROM academy.tenants WHERE id = _tenant_id AND status = 'active') THEN
    RAISE EXCEPTION 'Academy not accepting registrations';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM academy.fee_plans WHERE id = _fee_plan_id AND tenant_id = _tenant_id AND active = true) THEN
    RAISE EXCEPTION 'Invalid fee plan';
  END IF;
  IF _batch_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM academy.batches WHERE id = _batch_id AND tenant_id = _tenant_id AND active = true) THEN
    RAISE EXCEPTION 'Invalid batch';
  END IF;

  -- 8 registration submissions per phone per academy per 10 minutes.
  IF NOT academy.check_rate_limit(
       'reg:' || _tenant_id::text || ':' || regexp_replace(btrim(_phone), '\D', '', 'g'),
       8, 600) THEN
    RAISE EXCEPTION 'Too many submissions. Please try again in a few minutes.';
  END IF;

  INSERT INTO academy.registrations (
    tenant_id, name, phone, whatsapp, guardian_name, guardian_phone,
    dob, batch_id, fee_plan_id, status, payment_status, policy_acceptances
  ) VALUES (
    _tenant_id, btrim(_name), btrim(_phone), NULLIF(btrim(_whatsapp),''),
    NULLIF(btrim(_guardian_name),''), NULLIF(btrim(_guardian_phone),''),
    _dob, _batch_id, _fee_plan_id, 'new', 'pending',
    COALESCE(_policy_acceptances, '[]'::jsonb)
  ) RETURNING id INTO new_id;

  IF _lead_id IS NOT NULL THEN
    UPDATE academy.leads
       SET converted_registration_id = new_id,
           pipeline_stage = CASE WHEN pipeline_stage IN ('converted','rejected') THEN pipeline_stage ELSE 'approved' END
     WHERE id = _lead_id AND tenant_id = _tenant_id;

    INSERT INTO academy.admission_timeline
      (tenant_id, lead_id, registration_id, event_type, to_stage, remark)
    VALUES
      (_tenant_id, _lead_id, new_id, 'registration_submitted', 'approved', 'Registration form submitted');
  END IF;

  RETURN new_id;
END; $$;


--
-- Name: subscription_platform_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.subscription_platform_snapshot() RETURNS TABLE(plan_tier text, tenant_count bigint, active_count bigint, trial_count bigint, suspended_count bigint)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
  SELECT
    COALESCE(t.plan_tier, 'starter') AS plan_tier,
    COUNT(*)::bigint AS tenant_count,
    COUNT(*) FILTER (WHERE t.subscription_status = 'paid')::bigint AS active_count,
    COUNT(*) FILTER (WHERE t.subscription_status = 'trial')::bigint AS trial_count,
    COUNT(*) FILTER (WHERE t.status = 'suspended')::bigint AS suspended_count
  FROM academy.tenants t
  WHERE academy.is_platform_admin(auth.uid())
  GROUP BY COALESCE(t.plan_tier, 'starter');
$$;


