CREATE FUNCTION academy.track_website_event(_slug text, _event_type text, _event_key text DEFAULT NULL::text, _metadata jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
  v_tenant_id UUID;
BEGIN
  SELECT id INTO v_tenant_id FROM academy.tenants
    WHERE slug = _slug OR custom_domain = _slug
    LIMIT 1;
