--
-- Name: update_my_student_profile(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.update_my_student_profile(_patch jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE
  _id uuid;
BEGIN
  SELECT id INTO _id FROM academy.students WHERE user_id = auth.uid() LIMIT 1;
  IF _id IS NULL THEN
    RAISE EXCEPTION 'No student record linked to this account';
  END IF;

  UPDATE academy.students SET
    phone = COALESCE(NULLIF(_patch->>'phone',''), phone),
    email = COALESCE(NULLIF(_patch->>'email',''), email),
    dob = COALESCE(NULLIF(_patch->>'dob','')::date, dob),
    gender = COALESCE(NULLIF(_patch->>'gender',''), gender),
    address = COALESCE(NULLIF(_patch->>'address',''), address),
    city = COALESCE(NULLIF(_patch->>'city',''), city),
    state = COALESCE(NULLIF(_patch->>'state',''), state),
    pincode = COALESCE(NULLIF(_patch->>'pincode',''), pincode),
    guardian_name = COALESCE(NULLIF(_patch->>'guardian_name',''), guardian_name),
    guardian_phone = COALESCE(NULLIF(_patch->>'guardian_phone',''), guardian_phone),
    emergency_contact_name = COALESCE(NULLIF(_patch->>'emergency_contact_name',''), emergency_contact_name),
    emergency_contact_phone = COALESCE(NULLIF(_patch->>'emergency_contact_phone',''), emergency_contact_phone),
    blood_group = COALESCE(NULLIF(_patch->>'blood_group',''), blood_group),
    school_college = COALESCE(NULLIF(_patch->>'school_college',''), school_college),
    playing_role = COALESCE(NULLIF(_patch->>'playing_role',''), playing_role),
    batting_style = COALESCE(NULLIF(_patch->>'batting_style',''), batting_style),
    bowling_style = COALESCE(NULLIF(_patch->>'bowling_style',''), bowling_style),
    medical_notes = COALESCE(NULLIF(_patch->>'medical_notes',''), medical_notes),
    profile_completed_at = COALESCE(profile_completed_at, now()),
    updated_at = now()
  WHERE id = _id;

  RETURN _id;
END;
$$;


--
-- Name: validate_student_lifecycle(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.validate_student_lifecycle() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'academy'
    AS $$
BEGIN
  IF NEW.lifecycle_status NOT IN (
    'applied','registration_in_progress','registration_submitted','registration_fee_pending',
    'under_review','approved','rejected','waitlisted','imported','invitation_sent',
    'activated','profile_completed','fee_plan_assigned','batch_assigned',
    'active','inactive','transferred','alumni'
  ) THEN
    RAISE EXCEPTION 'Invalid lifecycle_status: %', NEW.lifecycle_status;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: void_billing_invoice(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION academy.void_billing_invoice(_invoice_id uuid, _reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'academy'
    AS $$
DECLARE inv academy.billing_invoices%ROWTYPE; paid numeric;
BEGIN
  SELECT * INTO inv FROM academy.billing_invoices WHERE id = _invoice_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Invoice not found'; END IF;
  IF NOT (academy.is_tenant_owner(auth.uid(), inv.tenant_id) OR academy.is_platform_admin(auth.uid())) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  IF inv.status IN ('void','paid') THEN RAISE EXCEPTION 'Cannot void a % invoice', inv.status; END IF;

  SELECT COALESCE(SUM(a.amount),0) INTO paid
    FROM academy.billing_payment_allocations a
    JOIN academy.billing_payments p ON p.id = a.payment_id AND p.status = 'succeeded'
   WHERE a.invoice_id = _invoice_id;
  IF paid > 0 THEN RAISE EXCEPTION 'Cannot void invoice with successful payments; use adjustments'; END IF;

  UPDATE academy.billing_invoices SET status = 'void', notes = COALESCE(notes,'') || E'\nVOID: ' || _reason
   WHERE id = _invoice_id;
  UPDATE academy.billing_charges SET status = 'void'
   WHERE id IN (SELECT charge_id FROM academy.billing_invoice_lines WHERE invoice_id = _invoice_id AND charge_id IS NOT NULL);

  INSERT INTO academy.billing_audit_log(tenant_id, entity_type, entity_id, action, actor_id, metadata)
  VALUES (inv.tenant_id, 'invoice', _invoice_id, 'voided', auth.uid(), jsonb_build_object('reason', _reason));
  RETURN _invoice_id;
END; $$;


