    tenant_id uuid NOT NULL,
    student_id uuid NOT NULL,
    status academy.attendance_status DEFAULT 'present'::academy.attendance_status NOT NULL,
    note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    check_in_at timestamp with time zone,
    check_out_at timestamp with time zone,
    source academy.attendance_source DEFAULT 'manual'::academy.attendance_source NOT NULL,
    marked_by uuid,
    check_in_meta jsonb DEFAULT '{}'::jsonb NOT NULL,
    check_out_meta jsonb DEFAULT '{}'::jsonb NOT NULL,
    corrects_id uuid,
    superseded_by uuid,
    duration_minutes integer GENERATED ALWAYS AS (
CASE
    WHEN ((check_in_at IS NOT NULL) AND (check_out_at IS NOT NULL)) THEN GREATEST(0, ((EXTRACT(epoch FROM (check_out_at - check_in_at)))::integer / 60))
    ELSE NULL::integer
END) STORED,
    visit_type text
);

