--
-- Name: attendance_today; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW academy.attendance_today WITH (security_invoker='on') AS
 SELECT m.id AS mark_id,
    m.tenant_id,
    m.student_id,
    m.session_id,
    s.session_date,
    s.batch_id,
    m.status,
    m.check_in_at,
    m.check_out_at,
        CASE
            WHEN ((m.check_out_meta ->> 'exclude_from_hours'::text) = 'true'::text) THEN 0
            ELSE m.duration_minutes
        END AS duration_minutes,
    m.source,
    m.marked_by,
        CASE
            WHEN (m.status = 'absent'::academy.attendance_status) THEN 'absent'::text
            WHEN ((m.check_in_at IS NOT NULL) AND (m.check_out_at IS NULL)) THEN 'in_academy'::text
            WHEN ((m.check_in_at IS NOT NULL) AND (m.check_out_at IS NOT NULL)) THEN 'checked_out'::text
            ELSE 'not_marked'::text
        END AS current_state,
    COALESCE(((m.check_out_meta ->> 'auto_checkout'::text) = 'true'::text), false) AS auto_checked_out
   FROM (academy.attendance_marks m
     JOIN academy.attendance_sessions s ON ((s.id = m.session_id)))
  WHERE ((s.session_date = CURRENT_DATE) AND (m.superseded_by IS NULL));


--
-- Name: attendance_visits; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW academy.attendance_visits WITH (security_invoker='on') AS
 SELECT m.id AS mark_id,
    m.tenant_id,
    m.student_id,
    m.session_id,
    s.session_date,
    s.batch_id,
    m.status,
    m.check_in_at,
    m.check_out_at,
        CASE
            WHEN ((m.check_out_meta ->> 'exclude_from_hours'::text) = 'true'::text) THEN 0
            ELSE m.duration_minutes
        END AS duration_minutes,
    m.source,
    m.marked_by,
    m.visit_type,
    m.note,
    m.created_at
   FROM (academy.attendance_marks m
     JOIN academy.attendance_sessions s ON ((s.id = m.session_id)))
  WHERE ((m.superseded_by IS NULL) AND (m.status = 'present'::academy.attendance_status));


