--
-- Name: mc_public_squad_players; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW academy.mc_public_squad_players WITH (security_invoker=off) AS
 SELECT s.match_id,
    s.team_id,
    s.id AS squad_row_id,
    s.athlete_profile_id,
    s.external_player_name,
    COALESCE(st.name, s.external_player_name) AS display_name,
    st.photo_url,
    s.role,
    s.batting_order,
    s.is_playing,
    s.is_captain,
    s.is_vice_captain,
    s.is_keeper,
    s.is_substitute
   FROM ((academy.mc_match_squads s
     LEFT JOIN academy.mc_athlete_profiles ap ON ((ap.id = s.athlete_profile_id)))
     LEFT JOIN academy.students st ON ((st.id = ap.student_id)))
  WHERE (EXISTS ( SELECT 1
           FROM academy.mc_matches m
          WHERE ((m.id = s.match_id) AND (((m.visibility = 'public'::text) AND academy.is_active_tenant(m.tenant_id)) OR (EXISTS ( SELECT 1
                   FROM academy.mc_tournaments t
                  WHERE ((t.id = m.tournament_id) AND (t.published = true) AND (t.visibility = 'public'::text))))))));


--
-- Name: VIEW mc_public_squad_players; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW academy.mc_public_squad_players IS 'Public projection of match squads. Exposes only display_name, photo_url, role, batting_order and flags — never DOB / medical / guardian / contact / address / email.';


