--
-- Name: students_scorer_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW academy.students_scorer_view WITH (security_invoker='on') AS
 SELECT id,
    tenant_id,
    name,
    player_id,
    photo_url
   FROM academy.students s;


--
-- Name: students_scoring_directory; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW academy.students_scoring_directory WITH (security_invoker=off) AS
 SELECT id,
    tenant_id,
    name,
    photo_url,
    player_id,
    dob,
    gender,
    batch_id,
    status,
        CASE
            WHEN (academy.is_tenant_member(auth.uid(), tenant_id) OR academy.is_platform_admin(auth.uid())) THEN phone
            ELSE NULL::text
        END AS phone
   FROM academy.students s
  WHERE (academy.is_tenant_member(auth.uid(), tenant_id) OR academy.is_platform_admin(auth.uid()) OR academy.is_match_scorer(auth.uid(), tenant_id));


