--
-- Name: tenants; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE academy.tenants (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    slug text NOT NULL,
    name text NOT NULL,
    tagline text,
    custom_domain text,
    logo_url text,
    primary_color text DEFAULT '#1d4ed8'::text NOT NULL,
    secondary_color text DEFAULT '#0f172a'::text NOT NULL,
    niche text DEFAULT 'academy'::text NOT NULL,
    features jsonb DEFAULT '{"attendance": false, "fee_tracking": true, "powered_by_badge": true, "whatsapp_reminders": false, "online_registration": true}'::jsonb NOT NULL,
    phone text,
    whatsapp text,
    email text,
    address text,
    upi_id text,
    upi_qr_url text,
    status text DEFAULT 'active'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    fee_cycle text DEFAULT 'calendar_month'::text NOT NULL,
    monthly_price integer DEFAULT 0 NOT NULL,
    setup_fee integer DEFAULT 0 NOT NULL,
    billing_day integer DEFAULT 1 NOT NULL,
    last_paid_date date,
    subscription_status text DEFAULT 'due'::text NOT NULL,
    platform_notes text,
    player_prefix text,
    short_name text,
    show_billing_to_parents boolean DEFAULT false NOT NULL,
    sport_id text,
    online_payments_enabled boolean DEFAULT false NOT NULL,
    bank_account_name text,
    bank_account_number text,
    bank_ifsc text,
    payment_instructions text,
    plan_tier text DEFAULT 'starter'::text NOT NULL,
    trial_ends_at timestamp with time zone,
    current_period_end timestamp with time zone,
    feature_overrides jsonb DEFAULT '{}'::jsonb NOT NULL,
    usage_limits jsonb DEFAULT '{}'::jsonb NOT NULL,
    grace_ends_at timestamp with time zone,
    registration_pdf_url text,
    page_hero_images jsonb DEFAULT '{}'::jsonb NOT NULL,
    show_fees_tab boolean DEFAULT true NOT NULL,
    attendance_qr_enabled boolean DEFAULT false NOT NULL,
    attendance_qr_token text,
    geo_lat double precision,
    geo_lng double precision,
    geo_radius_m integer DEFAULT 150 NOT NULL,
    attendance_qr_min_gap_seconds integer DEFAULT 120 NOT NULL,
    admission_fee_enabled boolean DEFAULT true,
    gender_pricing_enabled boolean DEFAULT false,
    CONSTRAINT tenants_billing_day_chk CHECK (((billing_day >= 1) AND (billing_day <= 28))),
    CONSTRAINT tenants_monthly_price_nn CHECK ((monthly_price >= 0)),
    CONSTRAINT tenants_plan_tier_check CHECK ((plan_tier = ANY (ARRAY['starter'::text, 'professional'::text, 'enterprise'::text]))),
    CONSTRAINT tenants_setup_fee_nn CHECK ((setup_fee >= 0)),
    CONSTRAINT tenants_sub_status_chk CHECK ((subscription_status = ANY (ARRAY['paid'::text, 'due'::text, 'overdue'::text])))
);


--
-- Name: COLUMN tenants.admission_fee_enabled; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN academy.tenants.admission_fee_enabled IS 'Toggle to enable or disable one-time admission fee for new registrations';


--
-- Name: COLUMN tenants.gender_pricing_enabled; Type: COMMENT; Schema: public; Owner: -
