--
-- Name: tenants_public_directory; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW academy.tenants_public_directory WITH (security_invoker=off) AS
 SELECT id,
    slug,
    name,
    short_name,
    tagline,
    custom_domain,
    logo_url,
    primary_color,
    secondary_color,
    niche,
    features,
    phone,
    whatsapp,
    email,
    address,
    status,
    fee_cycle,
    player_prefix,
    registration_pdf_url,
    page_hero_images,
    show_fees_tab,
    gender_pricing_enabled,
    admission_fee_enabled,
    NULL::text AS upi_id,
    NULL::text AS upi_qr_url
   FROM academy.tenants
  WHERE (status = 'active'::text);


